content:
:root {
  --bg:          #f2f6f1;
  --bg-2:        #e6efe4;
  --white:       #ffffff;
  --ink:         #0a1c12;
  --muted:       #52665a;
  --green:       #1a7a32;
  --green-mid:   #249640;
  --green-deep:  #071910;
  --green-cta:   #062812;
  --green-card:  #176b2c;
  --green-light: #e8f4ea;
  --line:        #c9ddcf;
  --shadow-sm:   0 2px 10px rgba(7, 25, 16, 0.07);
  --shadow:      0 14px 40px rgba(7, 25, 16, 0.11);
  --shadow-lg:   0 28px 72px rgba(7, 25, 16, 0.16);
  --radius:      18px;
  --radius-sm:   12px;
  --header:      92px;
  --wrap:        1180px;
  --ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --font-display: "Cormorant Garamond", "Times New Roman", Georgia, serif;
  --font-body: "Manrope", "Segoe UI", sans-serif;
}

/* ── KEYFRAMES ──────────────────────────────── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(32px); }
  to   { opacity: 1; transform: none; }
}
@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes heroKenBurns {
  from { transform: scale(1); }
  to   { transform: scale(1.1); }
}
@keyframes leafDrift1 {
  0%,100% { transform: translate(0,0) rotate(-8deg) scale(1); }
  35%     { transform: translate(-18px,-26px) rotate(5deg) scale(1.05); }
  70%     { transform: translate(8px,-14px) rotate(-3deg) scale(0.97); }
}
@keyframes leafDrift2 {
  0%,100% { transform: translate(0,0) rotate(6deg) scale(1); }
  40%     { transform: translate(16px,-22px) rotate(-9deg) scale(1.06); }
  80%     { transform: translate(-6px,-10px) rotate(8deg) scale(0.98); }
}
@keyframes leafDrift3 {
  0%,100% { transform: translate(0,0) rotate(0deg) scale(1); }
  50%     { transform: translate(-14px,-30px) rotate(14deg) scale(1.07); }
}
@keyframes pulseGlow {
  0%,100% { box-shadow: 0 4px 18px rgba(30,135,54,0.25); }
  50%     { box-shadow: 0 4px 18px rgba(30,135,54,0.25), 0 0 0 8px rgba(30,135,54,0.14); }
}
@keyframes scrollBounce {
  0%,100% { transform: translateY(0); opacity: 0.9; }
  50%     { transform: translateY(10px); opacity: 0.35; }
}
@keyframes rotateBorder {
  to { transform: rotate(360deg); }
}
@keyframes stepLine {
  from { width: 0; }
  to   { width: 100%; }
}
@keyframes cardIn {
  from { opacity: 0; transform: translateY(20px) scale(0.97); }
  to   { opacity: 1; transform: none; }
}

/* ── SCROLL REVEAL ──────────────────────────── */
.fade-up {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.65s var(--ease-spring), transform 0.65s var(--ease-spring);
  will-change: opacity, transform;
}
.fade-up.in-view { opacity: 1; transform: none; }

/* ── Directional reveal ── */
.reveal {
  opacity: 0;
  transition: opacity 0.7s var(--ease-spring), transform 0.7s var(--ease-spring), filter 0.7s ease;
  will-change: opacity, transform;
}
.reveal-up    { transform: translateY(36px); }
.reveal-left  { transform: translateX(-40px); }
.reveal-right { transform: translateX(40px); }
.reveal-zoom  { transform: scale(0.92); }
.reveal-blur  { filter: blur(12px); transform: translateY(20px); }
.reveal.in-view { opacity: 1; transform: none; filter: none; }

/* ── Zoom image (scroll reveal + hover) ── */
.zoom-img {
  overflow: hidden;
  border-radius: inherit;
  position: relative;
}
.zoom-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transform: scale(1.18);
  opacity: 0;
  transition: transform 1.1s var(--ease-spring), opacity 0.9s ease;
  will-change: transform, opacity;
}
.zoom-img.in-view img { transform: scale(1); opacity: 1; }
.zoom-img:hover img { transform: scale(1.06); transition: transform 0.6s ease; }

/* ── Split text (word reveal) ── */
.split-text .split-word {
  display: inline-block;
  opacity: 0;
  transform: translateY(0.5em) rotate(2deg);
  transition: opacity 0.5s ease, transform 0.6s var(--ease-spring);
  will-change: opacity, transform;
}
.split-text.in-view .split-word { opacity: 1; transform: none; }
.split-text.is-manual .split-word {
  opacity: 0;
  transform: none;
  transition: none;
  will-change: transform, opacity;
}

@media (prefers-reduced-motion: reduce) {
  .reveal, .zoom-img img, .split-text .split-word,
  .fade-up { transition: none !important; opacity: 1 !important; transform: none !important; filter: none !important; }
  .home-hero-copy .home-hero-brand,
  .home-hero-copy h1,
  .home-hero-copy .home-hero-lede,
  .home-hero-copy .home-hero-actions,
  .home-hero-copy .home-hero-rule,
  .home-hero-scroll { opacity: 1 !important; transform: none !important; }
  .about-motion .about-copy-anim > *,
  .about-motion .about-video-anim,
  .about-motion .video-card-media,
  .about-motion .video-play,
  .about-motion .video-caption { opacity: 1 !important; transform: none !important; }
  .home-hero-video,
  .hero-bg-video,
  .video-card-media { display: none !important; }
  .home-hero-poster { opacity: 1 !important; animation: none !important; transform: none !important; }
  .home-hero-veil,
  .hero-bg-frost {
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    width: 100%;
    background: rgba(4, 20, 10, 0.72);
    mask-image: none;
    -webkit-mask-image: none;
  }
  .svc-bento-tile.is-active { animation: none; }
  .svc-bento-tile.is-active .svc-bento-tile-icon { animation: none; }
}

* { box-sizing: border-box; }
html {
  scroll-behavior: smooth;
  overflow-x: hidden;
  overflow-x: clip;
  max-width: 100%;
}
body {
  margin: 0;
  overflow-x: hidden;
  overflow-x: clip;
  max-width: 100%;
  background:
    radial-gradient(ellipse 80% 50% at 10% -10%, rgba(30, 135, 54, 0.07), transparent 55%),
    radial-gradient(ellipse 60% 40% at 100% 0%, rgba(8, 47, 23, 0.04), transparent 50%),
    var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  letter-spacing: -0.011em;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; text-decoration: none; }
button, input, select, textarea { font-family: inherit; }
img, video { max-width: 100%; display: block; }
.wrap { width: min(var(--wrap), calc(100% - 48px)); margin: 0 auto; max-width: 100%; }
.wrap-wide { width: min(1440px, calc(100% - 40px)); max-width: 100%; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 0;
  cursor: pointer;
  border-radius: var(--radius-sm);
  padding: 13px 22px;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: -0.015em;
  transition: transform 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
}
.btn svg { flex: none; transition: transform 0.25s ease; }
.btn:hover { transform: translateY(-2px); }
.btn:active { transform: translateY(0); }
.btn:hover svg { transform: translateX(3px); }
.btn:focus-visible { outline: 2px solid var(--green-mid); outline-offset: 3px; }
.btn-green {
  position: relative;
  overflow: hidden;
  background: linear-gradient(160deg, #1f8f3a 0%, #146b2a 55%, #0f5622 100%);
  color: #fff;
  box-shadow: 0 10px 28px rgba(16, 80, 36, 0.28);
}
/* subtle sheen sweep on hover */
.btn-green::after {
  content: "";
  position: absolute;
  top: 0;
  left: -60%;
  width: 40%;
  height: 100%;
  background: linear-gradient(100deg, transparent, rgba(255,255,255,0.28), transparent);
  transform: skewX(-18deg);
  transition: left 0.55s ease;
}
.btn-green:hover { box-shadow: 0 10px 26px rgba(30,135,54,0.42); }
.btn-green:hover::after { left: 120%; }
.btn-pulse { animation: pulseGlow 2.4s ease-in-out infinite; }
.btn-light { background: #fff; color: var(--green-deep); box-shadow: 0 4px 14px rgba(0,0,0,0.12); }
.btn-light:hover { background: #f0fbf3; box-shadow: 0 8px 22px rgba(0,0,0,0.16); }
.btn-outline {
  background: transparent;
  color: var(--green-deep);
  border: 1.5px solid var(--line);
  padding: 9px 18px;
  font-size: 13.5px;
  font-weight: 650;
}
.btn-outline:hover { border-color: var(--green); color: var(--green); background: var(--green-light); }
.btn-ghost {
  background: rgba(255,255,255,0.12);
  color: #fff;
  border: 1.5px solid rgba(255,255,255,0.55);
  backdrop-filter: blur(4px);
}
.btn-ghost:hover { background: rgba(255,255,255,0.22); border-color: rgba(255,255,255,0.90); }

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--green);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.eyebrow::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 40;
  height: var(--header);
  background: rgba(242, 246, 241, 0.86);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border-bottom: 1px solid transparent;
  transition: background 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}
.header.scrolled {
  background: rgba(242, 246, 241, 0.96);
  border-bottom-color: var(--line);
  box-shadow: 0 8px 28px rgba(7, 25, 16, 0.08);
}
.header-inner {
  height: 100%;
  width: min(1240px, calc(100% - 40px));
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 28px;
}
.brand-logo-link {
  display: inline-flex;
  align-items: center;
  flex: none;
  text-decoration: none;
  line-height: 0;
  min-width: 0;
}
.brand-logo {
  display: block;
  width: auto;
  max-width: none;
  object-fit: contain;
  object-position: center;
}
.brand-logo-header-wrap,
.brand-logo-footer-wrap {
  display: inline-flex;
  align-items: center;
  gap: 0;
}
.brand-logo-header {
  height: clamp(48px, 5.2vw, 70px);
  width: auto;
  max-width: min(340px, 36vw);
  min-width: 0;
  background: transparent;
}
.brand-logo-wordmark {
  display: flex;
  flex-direction: column;
  gap: 1px;
  line-height: 1.15;
}
.brand-logo-wordmark strong {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--ink);
}
.brand-logo-wordmark em {
  font-style: normal;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}
.brand-logo-wordmark-header strong {
  font-size: 17px;
  color: var(--green-deep);
}
.brand-logo-footer-wrap {
  padding: 16px 20px;
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.2);
  max-width: 340px;
}
.brand-logo-footer {
  height: 78px;
  width: auto;
  max-width: 340px;
  min-width: 0;
  background: transparent;
  filter: none;
}
.brand-logo-footer-wrap .brand-logo-wordmark strong {
  font-size: 16px;
  color: var(--green-deep);
}
.brand-logo-link-footer:hover .brand-logo-footer-wrap {
  transform: translateY(-2px);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.32);
  transition: transform 0.22s ease, box-shadow 0.22s ease;
}
.brand-logo-link-header:hover { opacity: 0.92; }
.nav { display: flex; align-items: center; gap: 22px; margin-left: auto; }
.nav a, .nav-drop > button, .nav-drop-link, .nav-drop-chev {
  background: none;
  border: 0;
  padding: 0;
  color: #2c3d34;
  font-size: 14.5px;
  font-weight: 550;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.nav a:hover, .nav-drop > button:hover, .nav-drop-link:hover, .nav-drop-chev:hover { color: var(--green); }
.nav a.active, .nav-drop > button.active, .nav-drop-link.active { color: var(--green); }
.nav a.active, .nav-drop-link.active { color: var(--green-deep); font-weight: 700; }
.nav-drop { position: relative; display: inline-flex; align-items: center; gap: 2px; }
/* Invisible hover bridge — keeps dropdown open while crossing the gap */
.nav-drop::after {
  content: "";
  position: absolute;
  top: 100%;
  left: -12px;
  right: -12px;
  height: 18px;
  display: none;
}
.nav-drop:hover::after,
.nav-drop:focus-within::after,
.nav-drop.is-open::after { display: block; }
.nav-menu {
  position: absolute;
  top: calc(100% + 12px);
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  width: 280px;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 16px;
  box-shadow: 0 18px 50px rgba(22, 48, 32, 0.14);
  padding: 8px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease, visibility 0.2s;
  z-index: 60;
}
.nav-drop:hover .nav-menu,
.nav-drop:focus-within .nav-menu,
.nav-drop.is-open .nav-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}
.nav-drop-chev {
  padding: 4px 2px 0 !important;
  line-height: 1;
  transition: transform 0.2s ease, color 0.15s ease;
}
.nav-drop:hover .nav-drop-chev,
.nav-drop.is-open .nav-drop-chev,
.nav-drop:focus-within .nav-drop-chev {
  transform: rotate(180deg);
  color: var(--green);
}
.nav-menu a {
  display: block;
  padding: 10px 12px;
  border-radius: 10px;
  font-size: 13.5px;
  font-weight: 600;
  transition: background 0.15s ease, color 0.15s ease;
}
.nav-menu a:hover { background: #f3f8f3; color: var(--green); }
.nav-all-services {
  background: var(--green-light) !important;
  color: var(--green) !important;
  font-weight: 700 !important;
  display: flex !important;
  justify-content: space-between;
  align-items: center;
}
.nav-all-services:hover { background: var(--green) !important; color: #fff !important; }
.nav-menu-sep { height: 1px; background: var(--line); margin: 6px 8px; }
.header-actions { display: flex; align-items: center; gap: 10px; margin-left: 8px; }
.header-phone {
  font-size: 13.5px;
  font-weight: 700;
  color: var(--green-deep);
  letter-spacing: -0.01em;
  white-space: nowrap;
}
.header-phone:hover { color: var(--green); }
.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 0;
  background: transparent;
  color: var(--green-deep);
  display: grid;
  place-items: center;
  cursor: pointer;
}
.icon-btn:hover { background: rgba(27, 67, 50, 0.06); }
.menu-btn { display: none; }

/* ── Mobile: push actions to far right ── */
@media (max-width: 820px) {
  .header-inner { justify-content: space-between; }
  .header-actions { margin-left: auto; gap: 6px; }
  .icon-btn { width: 38px; height: 38px; }
}

/* Hero */
/* ══════════════════════════════════════════
   HOME HERO — cinematic full-bleed
══════════════════════════════════════════ */
.home-hero {
  position: relative;
  isolation: isolate;
  min-height: calc(100svh - var(--header));
  min-height: calc(100vh - var(--header));
  display: flex;
  align-items: flex-end;
  color: #fff;
  background: #04140a;
  overflow: hidden;
}
.home-hero-media {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.home-hero-poster,
.home-hero-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 36%;
  pointer-events: none;
}
.home-hero-poster {
  z-index: 0;
  transform: scale(1.04);
}
.home-hero-video {
  z-index: 1;
  will-change: transform, opacity;
}
.home-hero.is-ready .home-hero-video {
  animation: homeHeroKen 28s ease-in-out infinite alternate;
}
@keyframes homeHeroKen {
  from { transform: scale(1.04); }
  to { transform: scale(1.1); }
}
.home-hero-veil {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    linear-gradient(
      108deg,
      rgba(2, 14, 8, 0.88) 0%,
      rgba(2, 14, 8, 0.62) 26%,
      rgba(2, 14, 8, 0.28) 48%,
      rgba(2, 14, 8, 0.1) 68%,
      rgba(2, 14, 8, 0.22) 100%
    ),
    linear-gradient(
      180deg,
      rgba(2, 12, 7, 0.32) 0%,
      transparent 26%,
      transparent 48%,
      rgba(2, 12, 7, 0.58) 78%,
      rgba(1, 10, 6, 0.82) 100%
    );
}
.home-hero-grain {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  opacity: 0.22;
  mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.55'/%3E%3C/svg%3E");
  background-size: 180px 180px;
}
.home-hero-frame {
  position: relative;
  z-index: 4;
  width: min(1240px, calc(100% - 80px));
  margin: 0 auto;
  padding: 48px 0 96px;
}
.home-hero-copy {
  position: relative;
  max-width: min(920px, 92vw);
}
.home-hero-copy::before {
  content: "";
  position: absolute;
  left: -12%;
  top: -18%;
  width: 78%;
  height: 118%;
  background: radial-gradient(
    ellipse at 30% 40%,
    rgba(4, 28, 14, 0.55) 0%,
    rgba(4, 28, 14, 0.18) 48%,
    transparent 72%
  );
  pointer-events: none;
  z-index: -1;
  filter: blur(2px);
}
.home-hero-brand {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(28px, 3.4vw, 42px);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.05;
  color: #fff;
  text-shadow: 0 2px 24px rgba(0, 0, 0, 0.35);
}
.home-hero-rule {
  display: block;
  width: 48px;
  height: 2px;
  margin: 18px 0 22px;
  background: linear-gradient(90deg, #7fd88a 0%, rgba(127, 216, 138, 0.15) 100%);
  border-radius: 2px;
}
.home-hero-title,
.home-hero h1 {
  margin: 0 0 18px;
  font-family: var(--font-display);
  font-size: clamp(38px, 4.4vw, 58px);
  font-weight: 600;
  line-height: 1.18;
  letter-spacing: -0.03em;
  max-width: none;
  color: #fff;
  text-shadow: 0 2px 28px rgba(0, 0, 0, 0.28);
}
.home-hero-title .home-hero-break {
  display: block;
}
.home-hero-lede {
  margin: 0 0 32px;
  max-width: 100%;
  font-size: 17px;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.84);
  font-weight: 500;
}
.home-hero-actions {
  display: flex;
  align-items: center;
  gap: 22px;
  flex-wrap: wrap;
}
.home-hero-cta {
  padding: 14px 22px;
  font-size: 14.5px;
  letter-spacing: 0.01em;
  box-shadow:
    0 10px 28px rgba(0, 0, 0, 0.28),
    0 0 0 1px rgba(255, 255, 255, 0.06) inset;
  transition: transform 0.35s var(--ease-spring), box-shadow 0.35s ease, background 0.25s ease;
}
.home-hero-cta:hover {
  transform: translateY(-2px);
  box-shadow:
    0 16px 36px rgba(0, 0, 0, 0.34),
    0 0 0 1px rgba(255, 255, 255, 0.1) inset;
}
.home-hero-cta-secondary {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.55);
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(8px);
}
.home-hero-cta-secondary:hover {
  background: rgba(255, 255, 255, 0.16);
  border-color: #fff;
  color: #fff;
}
.home-hero .watch {
  display: flex;
  align-items: center;
  gap: 12px;
  background: none;
  border: 0;
  color: #fff;
  cursor: pointer;
  text-align: left;
  padding: 4px;
  border-radius: 999px;
  transition: opacity 0.25s ease;
}
.home-hero .watch:hover { opacity: 0.88; }
.home-hero .watch:hover .play {
  background: rgba(255, 255, 255, 0.16);
  border-color: #fff;
  transform: scale(1.04);
}
.home-hero .play {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.75);
  display: grid;
  place-items: center;
  flex: none;
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: transform 0.35s var(--ease-spring), background 0.25s ease, border-color 0.25s ease;
}
.home-hero .play svg { margin-left: 2px; }
.home-hero .watch strong {
  display: block;
  font-size: 14.5px;
  font-weight: 700;
  letter-spacing: 0.01em;
}
.home-hero .watch em {
  display: block;
  font-style: normal;
  font-size: 12.5px;
  color: rgba(255, 255, 255, 0.68);
  margin-top: 2px;
}
.home-hero-scroll {
  position: absolute;
  z-index: 5;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: rgba(255, 255, 255, 0.55);
  pointer-events: none;
}
.home-hero-scroll-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}
.home-hero-scroll-line {
  width: 1px;
  height: 42px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.55), transparent);
  transform-origin: top center;
  animation: homeHeroScrollPulse 2.4s ease-in-out infinite;
}
@keyframes homeHeroScrollPulse {
  0%, 100% { transform: scaleY(1); opacity: 0.75; }
  50% { transform: scaleY(0.55); opacity: 0.3; }
}

@media (prefers-reduced-motion: reduce) {
  .home-hero.is-ready .home-hero-video,
  .home-hero-scroll-line {
    animation: none !important;
  }
}

h1, h2, .page-hero h1, .cta h2 {
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: -0.02em;
}

/* Legacy watch (non-hero pages / older blocks) */
.watch {
  display: flex;
  align-items: center;
  gap: 12px;
  background: none;
  border: 0;
  color: #fff;
  cursor: pointer;
  text-align: left;
  padding: 0;
}
.play {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,0.85);
  display: grid;
  place-items: center;
  flex: none;
  background: rgba(255,255,255,0.08);
}
.play svg { margin-left: 2px; }
.watch strong { display: block; font-size: 15px; font-weight: 700; }
.watch em { display: block; font-style: normal; font-size: 12.5px; color: rgba(255,255,255,0.75); margin-top: 1px; }

.features {
  width: min(1240px, calc(100% - 40px));
  margin: -50px auto 0;
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
.feature {
  background: #fff;
  border: 1px solid #e2ece2;
  border-radius: 18px;
  box-shadow: var(--shadow);
  padding: 18px 16px 18px 16px;
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 88px;
  transition: transform 0.22s ease, box-shadow 0.22s ease;
}
.feature:hover { transform: translateY(-3px); box-shadow: var(--shadow-lg); }
.feature img {
  width: 46px;
  height: 46px;
  object-fit: cover;
  border-radius: 50%;
  flex: none;
  box-shadow: 0 2px 8px rgba(30,135,54,0.15);
}
.feature h3 { margin: 0 0 3px; font-size: 14px; font-weight: 700; letter-spacing: -0.02em; line-height: 1.2; }
.feature p { margin: 0; color: var(--muted); font-size: 12.5px; line-height: 1.35; }

/* About */
.about { padding: 88px 0 36px; }
.about-grid {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  gap: 48px;
  align-items: center;
}
.about-grid > .fade-up.fill,
.about-grid > .about-video-anim.fill {
  display: flex;
  align-items: center;
  min-height: 0;
  height: auto;
}
.about-grid > .fade-up.fill > .video-card,
.about-grid > .about-video-anim.fill > .video-card {
  width: 100%;
  flex: none;
}
.about-cta-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 28px;
}
.about-copy-anim,
.about-video-anim {
  min-width: 0;
}
.about-motion .about-copy-anim > .eyebrow,
.about-motion .about-copy-anim > h2,
.about-motion .about-copy-anim > .lede,
.about-motion .about-copy-anim > .about-cta-row,
.about-motion .about-copy-anim .stat,
.about-motion .about-video-anim,
.about-motion .video-play,
.about-motion .video-caption {
  will-change: transform, opacity;
}
.about h2, .why h2, .services h2, .page-hero h1, .cta h2 {
  font-weight: 400;
  letter-spacing: -0.025em;
  line-height: 1.12;
  margin: 10px 0 14px;
}
.about h2 { font-size: 44px; max-width: 440px; line-height: 1.1; letter-spacing: -0.02em; color: var(--ink); }
.about .lede { color: var(--muted); max-width: 440px; margin: 0 0 26px; font-size: 15.5px; line-height: 1.70; }
/* Legacy .stats used on About/Testimonials pages */
.stats { display: flex; gap: 28px; margin-top: 34px; align-items: flex-start; }
.stat { text-align: center; width: 118px; }
.stat img {
  width: 74px;
  height: 74px;
  object-fit: cover;
  border-radius: 50%;
  margin: 0 auto 10px;
  background: #e8f6df;
  box-shadow: 0 4px 14px rgba(30,135,54,0.12);
}
.stat strong {
  display: block;
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 400;
  color: var(--green);
  line-height: 1;
  margin-bottom: 4px;
}
.stat span { display: block; font-size: 12.5px; font-weight: 500; letter-spacing: -0.01em; line-height: 1.3; color: #8b9790; }

.video-card {
  position: relative;
  border-radius: 22px;
  overflow: hidden;
  aspect-ratio: 16 / 10;
  height: auto;
  min-height: 0;
  background: #16301c;
  color: #fff;
  border: 0;
  width: 100%;
  cursor: pointer;
  text-align: left;
  padding: 0;
  display: block;
}
.video-card-media {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  display: block;
  pointer-events: none;
  transform: none;
  transform-origin: center center;
}
/* Hover zoom only when GSAP isn't driving (non-about cards) */
.video-card:hover .video-card-media {
  transform: scale(1.1);
  transition: transform 0.6s ease;
}
.about-motion .video-card .video-card-media,
.about-motion .video-card:hover .video-card-media {
  transition: none;
}
.video-card::after { z-index: 1; }
.video-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0.02) 40%, rgba(6, 20, 10, 0.18) 100%);
}
.video-play {
  position: absolute;
  z-index: 2;
  left: 50%;
  top: 42%;
  transform: translate(-50%, -50%);
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: rgba(255,255,255,0.96);
  color: var(--green-deep);
  display: grid;
  place-items: center;
  box-shadow: 0 10px 30px rgba(0,0,0,0.18);
}
.video-caption {
  position: absolute;
  z-index: 2;
  left: 18px;
  bottom: 18px;
  right: auto;
  max-width: 260px;
  background: #1a6d32;
  border-radius: 16px;
  padding: 16px 18px 14px;
  box-shadow: 0 14px 32px rgba(6, 20, 10, 0.28);
}
.video-caption strong { display: block; font-size: 17px; font-weight: 650; letter-spacing: -0.02em; line-height: 1.25; }
.video-caption span { display: inline-flex; align-items: center; gap: 6px; margin-top: 8px; font-size: 13px; font-weight: 600; }

/* Collage + why, side by side like the reference */
.pair { padding: 34px 0 8px; }
.pair-grid {
  display: grid;
  grid-template-columns: 1.02fr 0.98fr;
  gap: 36px;
  align-items: center;
}
.collage {
  display: grid;
  grid-template-columns: 0.62fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 8px;
  aspect-ratio: 430 / 270;
}
.collage img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 14px;
}
.c-path { grid-column: 1; grid-row: 1; object-position: center 40%; }
.c-flowers { grid-column: 1; grid-row: 2; object-position: center 58%; }
.c-right {
  grid-column: 2;
  grid-row: 1 / span 2;
  position: relative;
  min-height: 0;
}
.c-leaf {
  position: relative;
  z-index: 0;
  width: 100%;
  height: auto !important;
  display: block;
  object-fit: fill;
  border-radius: 14px;
}
.green-card {
  position: absolute;
  left: 0;
  right: 0;
  top: 78px;
  bottom: 0;
  background: #318432;
  color: #fff;
  border-radius: 18px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 18px 22px 16px;
}
.green-card h3 {
  margin: 0 0 8px;
  font-size: 25px;
  line-height: 1.1;
  letter-spacing: -0.03em;
  font-weight: 600;
}
.green-card p {
  margin: 0 0 16px;
  color: rgba(255,255,255,0.92);
  font-size: 13.5px;
  line-height: 1.45;
  font-weight: 450;
  max-width: 240px;
}
.green-card .btn {
  align-self: center;
  font-weight: 600;
  font-size: 13.5px;
  padding: 8px 16px;
  border-width: 1.5px;
  border-color: rgba(255,255,255,0.85);
}

.why-copy h2 {
  margin: 6px 0 10px;
  font-size: 32px;
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: #243f34;
}
.why-kicker {
  color: #9aa49c;
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.why-copy > p {
  margin: 0;
  max-width: none;
  color: #7d8a83;
  font-size: 14px;
  line-height: 1.55;
}
.why-copy .reasons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin-top: 26px;
}
.why-copy .reason {
  text-align: center;
  padding: 0 12px;
  position: relative;
}
.why-copy .reason + .reason::before {
  content: "";
  position: absolute;
  left: 0;
  top: 6px;
  bottom: 6px;
  width: 1px;
  background: #e3eae4;
}
.why-copy .reason img {
  width: 52px;
  height: 52px;
  object-fit: cover;
  object-position: center;
  border-radius: 50%;
  margin: 0 auto 8px;
  background: #e8f6e0;
}
.why-copy .reason h3 { margin: 0 0 2px; font-size: 13.5px; font-weight: 700; letter-spacing: -0.02em; color: #1a3328; }
.why-copy .reason p { margin: 0 auto; color: #8b9790; font-size: 12px; max-width: 120px; line-height: 1.3; }
.reasons { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.reason { text-align: center; }
.reason img { width: 64px; height: 64px; object-fit: cover; border-radius: 50%; margin: 0 auto 8px; }
.reason h3 { margin: 0 0 4px; font-size: 15px; }
.reason p { margin: 0; color: var(--muted); font-size: 13px; }

/* Services */
.services { padding: 72px 0 48px; background: var(--bg); }
.services-head { max-width: 680px; margin-bottom: 36px; }
.services h2 { font-size: 44px; max-width: 680px; font-weight: 400; letter-spacing: -0.02em; line-height: 1.12; }
.services .lede { color: var(--muted); margin: 8px 0 0; max-width: 540px; font-size: 15px; line-height: 1.65; }
.services-link-row { margin-top: 28px; }
.section-header h2 { font-size: 40px; }
.service-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.service-grid.wide { grid-template-columns: repeat(3, 1fr); margin-top: 18px; }

/* ── SERVICE CARD ── */
.service-card {
  background: #fff;
  border: 1px solid #e0ece0;
  border-radius: 20px;
  padding: 0;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  transition: transform 0.25s var(--ease-spring), box-shadow 0.25s ease;
  cursor: default;
}
.service-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 20px 48px rgba(14,35,24,0.13);
}
.service-photo {
  overflow: hidden;
  aspect-ratio: 16 / 10;
  background: #c8dbc8;
}
.service-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}
.service-card:hover .service-photo img { transform: scale(1.07); }
.service-body { padding: 12px 14px 14px; flex: 1; display: flex; flex-direction: column; }
.service-meta {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  margin-top: 6px;
}
.service-badge {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--green-light);
  color: var(--green);
  display: grid;
  place-items: center;
  flex: none;
  margin-top: -28px;
  border: 3px solid #fff;
  box-shadow: 0 2px 10px rgba(30,135,54,0.15);
  transition: background 0.2s ease;
}
.service-card:hover .service-badge { background: var(--green); color: #fff; }
.service-card h3 {
  margin: 0 0 3px;
  font-size: 14.5px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--ink);
  line-height: 1.25;
}
.service-card p { margin: 0; color: var(--muted); font-size: 13px; line-height: 1.4; }
.service-more {
  align-self: flex-start;
  margin-top: 14px;
  padding: 8px 14px;
  font-size: 13px;
  font-weight: 600;
  background: var(--green-light);
  color: var(--green);
  border: none;
  box-shadow: none;
  border-radius: 999px;
  transition: background 0.2s ease, color 0.2s ease;
}
.service-card:hover .service-more { background: var(--green); color: #fff; }

/* FadeUp inside service-grid — make grid aware */
.service-grid > .fade-up { display: flex; flex-direction: column; }
.service-grid > .fade-up > .service-card { flex: 1; }

/* ── STATS (floating white cards) ── */
.stats-float-wrap { padding: 0 18px; }
.stats-float-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 22px;
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  margin: -32px auto 0;
  position: relative;
  z-index: 3;
  max-width: var(--wrap);
}
.stats-float-item {
  text-align: center;
  padding: 26px 16px;
  border-right: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.stats-float-item:last-child { border-right: none; }
.stats-float-item strong {
  display: block;
  font-family: var(--font-display);
  font-size: 42px;
  font-weight: 400;
  color: var(--green);
  line-height: 1;
  letter-spacing: -0.03em;
}
.stats-float-item > span {
  display: block;
  font-size: 12.5px;
  color: var(--muted);
  margin-top: 2px;
}
.stats-float-cta { gap: 8px; }
.stats-float-cta > span { font-size: 11.5px; color: #9aab9c; }

/* ── ABOUT VISUAL (stacked images) ── */
.about-visual {
  position: relative;
  padding-bottom: 52px;
  padding-right: 32px;
}
.about-img-main {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: 22px;
  display: block;
}
.about-img-float {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 46%;
  aspect-ratio: 1;
  object-fit: cover;
  border-radius: 16px;
  border: 4px solid var(--bg);
  box-shadow: var(--shadow-lg);
}
.about-img-badge {
  position: absolute;
  top: 24px;
  left: 24px;
  background: rgba(255,255,255,0.96);
  border-radius: 14px;
  padding: 12px 16px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(8px);
  text-align: center;
  min-width: 90px;
}
.about-img-badge strong {
  display: block;
  font-family: var(--font-display);
  font-size: 28px;
  color: var(--green);
  font-weight: 400;
  line-height: 1;
}
.about-img-badge span { display: block; font-size: 11px; color: var(--muted); margin-top: 3px; }

/* ── CTA BANNER ── */
.cta-wrap { padding: 20px 0 0; }
.cta {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #062312 0%, #123d1f 60%, #082a14 100%);
  color: #fff;
  border-radius: 26px;
  padding: 44px 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  min-height: 140px;
}
.cta::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(30,135,54,0.18) 0%, transparent 60%);
  pointer-events: none;
}
.cta h2 { margin: 0 0 8px; font-size: 32px; }
.cta p { margin: 0; color: rgba(255,255,255,0.72); font-size: 15.5px; }

.cta-bleed {
  position: relative;
  overflow: hidden;
  width: 100%;
  margin: 56px 0 0;
  padding: 52px 0;
  color: #fff;
  background: linear-gradient(105deg, #04180d 0%, #0b2f18 42%, #145528 72%, #062312 100%);
}
.cta-bleed::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 120% at 50% 50%, rgba(30,135,54,0.22) 0%, transparent 55%),
    radial-gradient(circle at 12% 110%, rgba(8, 40, 18, 0.55) 0%, transparent 42%),
    radial-gradient(circle at 92% 115%, rgba(8, 40, 18, 0.5) 0%, transparent 40%);
  pointer-events: none;
}
.cta-bleed-inner {
  position: relative;
  z-index: 1;
  width: min(1180px, calc(100% - 64px));
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.cta-bleed h2 {
  margin: 0 0 10px;
  font-size: 36px;
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: #fff;
}
.cta-bleed p {
  margin: 0;
  color: rgba(255,255,255,0.72);
  font-size: 16px;
}
.cta-bleed .btn-light {
  flex: none;
  background: #e8f6e4;
  color: #0e3d1f;
  font-weight: 700;
}
.cta-bleed .btn-light:hover { background: #fff; }
.leaf {
  position: absolute;
  pointer-events: none;
  opacity: 0.22;
}
.leaf-br { right: -10px; bottom: -28px; width: 160px; }
.leaf-bl { left: -20px; bottom: -36px; width: 120px; transform: scaleX(-1); }

/* ══════════════════════════════════════════
   FOOTER — polished, structured
══════════════════════════════════════════ */
.footer {
  margin-top: 40px;
  background:
    radial-gradient(ellipse 60% 100% at 15% 0%, rgba(30,135,54,0.14) 0%, transparent 55%),
    #0a1f14;
  color: rgba(255,255,255,0.72);
}

/* ── CTA banner ── */
.footer-cta-banner {
  background: linear-gradient(120deg, #0a3018 0%, #145528 55%, #1e8736 130%);
  position: relative;
  overflow: hidden;
}
.footer-cta-banner::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 50% 120% at 88% 50%, rgba(155,224,168,0.20) 0%, transparent 60%);
  pointer-events: none;
}
.footer-cta-inner {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 34px 0;
}
.footer-cta-eyebrow {
  display: block;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #9be0a8;
  margin-bottom: 6px;
}
.footer-cta-text h3 {
  margin: 0;
  font-size: 30px;
  font-weight: 400;
  letter-spacing: -0.02em;
  color: #fff;
  font-family: var(--font-display);
}
.footer-cta-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: none;
}
.footer-cta-call {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 22px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 700;
  color: #0a3018;
  background: #fff;
  box-shadow: 0 8px 22px rgba(0,0,0,0.18);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.footer-cta-call:hover { transform: translateY(-2px); box-shadow: 0 12px 28px rgba(0,0,0,0.26); }
.footer-cta-call svg { flex: none; }
.footer-cta-quote {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 22px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 700;
  color: #fff;
  background: rgba(255,255,255,0.12);
  border: 1.5px solid rgba(255,255,255,0.35);
  transition: background 0.18s ease, transform 0.18s ease;
}
.footer-cta-quote:hover { background: rgba(255,255,255,0.22); transform: translateY(-2px); }
.footer-cta-quote svg { flex: none; }

/* ── Main grid ── */
.footer-grid {
  display: grid;
  grid-template-columns: minmax(240px, 1.05fr) minmax(0, 1.95fr);
  gap: 48px;
  padding: 52px 0 36px;
  align-items: start;
}

/* Brand column */
.footer-brand-col { display: flex; flex-direction: column; gap: 18px; }
.footer-logo { margin-bottom: 6px; }
.footer-tagline {
  margin: 0;
  font-size: 14px;
  color: rgba(255,255,255,0.55);
  line-height: 1.65;
  max-width: 320px;
}

/* Contact list */
.footer-contact-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}
.footer-contact-list li { margin: 0; }
.footer-contact-list a,
.footer-contact-static {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 10px;
  border-radius: 12px;
  text-decoration: none;
  transition: background 0.18s ease;
}
.footer-contact-list a:hover { background: rgba(255,255,255,0.05); }
.footer-contact-ico {
  width: 44px;
  height: 44px;
  min-width: 44px;
  min-height: 44px;
  border-radius: 50%;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  flex: none;
  line-height: 0 !important;
  overflow: hidden;
  background: #fff;
  color: #0e5c28 !important;
  font-size: 0 !important;
  border: 0;
  box-shadow: 0 6px 16px rgba(0,0,0,0.18);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.footer-contact-ico svg {
  display: block !important;
  width: 18px !important;
  height: 18px !important;
  margin: 0 auto !important;
  flex: none;
}
.footer-contact-list a:hover .footer-contact-ico {
  transform: translateY(-2px) scale(1.06);
  box-shadow: 0 10px 22px rgba(0,0,0,0.22);
}
.footer-contact-ico-wa {
  background: #25D366 !important;
  color: #fff !important;
}
.footer-contact-ico-mail {
  background: #1e8736 !important;
  color: #fff !important;
}
.footer-contact-ico-pin {
  background: #9be0a8 !important;
  color: #062312 !important;
}
.footer-contact-text { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.footer-contact-text em {
  font-style: normal;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.42);
}
.footer-contact-text b {
  font-size: 13.5px;
  font-weight: 600;
  color: rgba(255,255,255,0.88);
  line-height: 1.4;
  word-break: break-word;
}
.footer-contact-list a:hover .footer-contact-text b { color: #fff; }

/* Link columns */
.footer-links-wrap {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px 36px;
  min-width: 0;
}
.footer-link-col { display: flex; flex-direction: column; min-width: 0; }
.footer h4 {
  margin: 0 0 16px;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
}
.footer-link-col a {
  font-size: 14px;
  padding: 6px 0;
  color: rgba(255,255,255,0.60);
  transition: color 0.18s ease, padding-left 0.18s ease;
  position: relative;
}
.footer-link-col a:hover { color: #fff; padding-left: 6px; }

/* Map band — full width under main grid */
.footer-map-band {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(260px, 1fr);
  gap: 24px;
  align-items: stretch;
  padding: 4px 0 48px;
}
.footer-map-embed {
  position: relative;
  width: 100%;
  min-height: 280px;
  height: 100%;
  border-radius: 18px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.28);
  background: #07180f;
}
.footer-map-embed iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  display: block;
}
.footer-map-info {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  padding: 32px 30px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.10);
}
.footer-map-ico {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #9be0a8;
  color: #062312;
  margin-bottom: 4px;
}
.footer-map-ico svg { display: block; }
.footer-map-info h4 {
  margin: 0;
  color: #9be0a8;
}
.footer-map-info p {
  margin: 0;
  font-size: 15px;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.78);
}
.footer-map-hours {
  font-size: 13px !important;
  color: rgba(255, 255, 255, 0.48) !important;
}
.footer-map-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 10px;
}
.footer-map-dir,
.footer-map-call {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 11px 16px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
  transition: transform 0.18s ease, background 0.18s ease;
  white-space: nowrap;
}
.footer-map-dir {
  background: #fff;
  color: #0e5c28;
}
.footer-map-dir:hover { transform: translateY(-1px); background: #f3fff5; }
.footer-map-call {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.22);
}
.footer-map-call:hover { background: rgba(255, 255, 255, 0.14); transform: translateY(-1px); }
.footer-map-call svg { flex: none; }

/* Bottom bar */
.footer-bottom-wrap { border-top: 1px solid rgba(255,255,255,0.08); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding: 18px 0;
  font-size: 12.5px;
  color: rgba(255,255,255,0.40);
}
.footer-bottom-right { color: rgba(255,255,255,0.52); font-weight: 600; }

/* ── Footer responsive ── */
@media (max-width: 1100px) {
  .footer-grid {
    grid-template-columns: 1fr 1.4fr;
    gap: 36px;
  }
  .footer-links-wrap { gap: 22px 24px; }
  .footer-map-band {
    grid-template-columns: 1.2fr 1fr;
    gap: 18px;
  }
  .footer-map-embed { min-height: 250px; }
}
@media (max-width: 900px) {
  .footer-grid { grid-template-columns: 1fr; gap: 32px; padding: 40px 0 28px; }
  .footer-links-wrap { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .footer-cta-inner { flex-direction: column; align-items: flex-start; gap: 18px; }
  .footer-cta-text h3 { font-size: 24px; }
  .footer-map-band {
    grid-template-columns: 1fr;
    gap: 14px;
    padding: 0 0 36px;
  }
  .footer-map-embed {
    min-height: 240px;
    height: 240px;
  }
  .footer-map-info { padding: 24px 22px; }
}
@media (max-width: 640px) {
  .footer-cta-actions {
    width: 100%;
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    align-items: center;
    gap: 8px;
  }
  .footer-cta-call,
  .footer-cta-quote {
    flex: 1 1 0;
    flex-grow: 1;
    flex-shrink: 1;
    flex-basis: 0;
    justify-content: center;
    align-items: center;
    min-width: 0;
    width: auto;
    height: auto;
    min-height: 0;
    max-height: none;
    padding: 8px 10px;
    font-size: 11.5px;
    line-height: 1.2;
    gap: 5px;
    white-space: nowrap;
  }
  .footer-cta-call svg,
  .footer-cta-quote svg {
    width: 13px;
    height: 13px;
  }
  .footer-cta-text h3 { font-size: 18px; line-height: 1.25; }
  .footer-cta-eyebrow { font-size: 10px; margin-bottom: 4px; letter-spacing: 0.1em; }
  .footer-cta-inner { padding: 18px 0; gap: 12px; }
  .footer-grid { padding: 32px 0 24px; gap: 26px; }
  .footer-tagline { max-width: 100%; }
  .footer-contact-list a { padding: 8px 6px; }
  .footer-links-wrap {
    grid-template-columns: 1fr 1fr;
    gap: 22px 16px;
  }
  .footer-link-col:last-child { grid-column: 1 / -1; }
  .footer-link-col a { font-size: 13.5px; padding: 5px 0; }
  .footer-map-band { padding: 0 0 28px; }
  .footer-map-embed {
    min-height: 210px;
    height: 210px;
    border-radius: 14px;
  }
  .footer-map-info {
    padding: 20px 18px;
    border-radius: 14px;
    gap: 8px;
  }
  .footer-map-ico { width: 40px; height: 40px; }
  .footer-map-info p { font-size: 14px; }
  .footer-map-actions {
    width: 100%;
    flex-direction: column;
    margin-top: 8px;
  }
  .footer-map-dir,
  .footer-map-call {
    width: 100%;
    flex: none;
    padding: 12px 16px;
  }
  .footer-bottom {
    justify-content: center;
    text-align: center;
    flex-direction: column;
    gap: 6px;
    padding: 16px 0 22px;
  }
}
@media (max-width: 420px) {
  .footer-cta-actions {
    flex-direction: row;
    flex-wrap: nowrap;
    gap: 6px;
  }
  .footer-cta-call,
  .footer-cta-quote {
    width: auto;
    flex: 1 1 0;
    padding: 7px 8px;
    font-size: 11px;
    border-radius: 999px;
  }
  .footer-cta-text h3 { font-size: 16px; }
  .footer-links-wrap { grid-template-columns: 1fr; gap: 20px; }
  .footer-link-col:last-child { grid-column: auto; }
  .footer-map-embed {
    min-height: 190px;
    height: 190px;
  }
}

/* Inner pages */
.page-hero {
  padding: 52px 0 72px;
  position: relative;
  background: linear-gradient(140deg, #031610 0%, #0a3018 55%, #104520 100%);
  color: #fff;
  overflow: hidden;
}
/* Background photo layer — blends with gradient */
.page-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--hero-img, none);
  background-size: cover;
  background-position: center 35%;
  opacity: 0.18;
  z-index: 0;
  mix-blend-mode: luminosity;
  transform: scale(1);
  animation: heroKenBurns 22s ease-in-out infinite alternate;
}
/* Dark gradient overlay on top of photo */
.page-hero::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(to right, rgba(3,22,16,0.72) 0%, rgba(3,22,16,0.28) 65%, rgba(3,22,16,0.08) 100%),
    radial-gradient(ellipse at 80% 40%, rgba(30,135,54,0.14) 0%, transparent 55%),
    radial-gradient(ellipse at 10% 100%, rgba(4,32,14,0.55) 0%, transparent 50%);
  pointer-events: none;
}
.page-hero .wrap { position: relative; z-index: 2; }
.page-hero .eyebrow { color: rgba(155,224,168,0.90); letter-spacing: 0.12em; }
.page-hero h1 {
  font-size: clamp(32px, 4.5vw, 54px);
  margin: 10px 0 14px;
  max-width: 720px;
  color: #fff;
  letter-spacing: -0.025em;
  line-height: 1.08;
  text-shadow: 0 2px 18px rgba(0,0,0,0.22);
}
.page-hero p  { color: rgba(255,255,255,0.74); max-width: 580px; margin: 0 0 20px; font-size: 16px; line-height: 1.65; }
.page-hero .breadcrumbs a { color: rgba(155,224,168,0.75); }
.page-hero .breadcrumbs span[aria-current] { color: rgba(255,255,255,0.90); }
.page-hero .bc-sep { color: rgba(255,255,255,0.25); }
/* btn-outline / btn-ghost inside dark hero must be visible */
.page-hero .btn-outline {
  color: rgba(255,255,255,0.92);
  border-color: rgba(255,255,255,0.38);
  background: rgba(255,255,255,0.09);
}
.page-hero .btn-outline:hover {
  color: #fff;
  border-color: rgba(255,255,255,0.80);
  background: rgba(255,255,255,0.18);
}
.blog-hero .btn-outline,
.blog-post-hero .btn-outline {
  color: rgba(255,255,255,0.92);
  border-color: rgba(255,255,255,0.38);
  background: rgba(255,255,255,0.09);
}
.blog-hero .btn-outline:hover,
.blog-post-hero .btn-outline:hover {
  color: #fff;
  border-color: rgba(255,255,255,0.80);
  background: rgba(255,255,255,0.18);
}
.blog-hero .hero-cta-row,
.blog-post-hero .hero-cta-row {
  position: relative;
  z-index: 2;
}

/* Blog-specific hero (has a cover image) */
.blog-post-hero {
  min-height: 440px;
  position: relative;
  display: flex;
  align-items: flex-end;
  background: #082f17 center / cover no-repeat;
  border-radius: 0;
  overflow: hidden;
}
.blog-post-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(4,14,8,0.90) 0%, rgba(4,14,8,0.40) 50%, rgba(4,14,8,0.08) 100%);
}
.blog-post-hero-copy {
  position: relative;
  z-index: 1;
  padding: 0 0 52px;
  width: 100%;
}

/* Blog cards */
.blog-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; }
.blog-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 20px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  text-decoration: none;
  transition: transform 0.22s var(--ease-spring), box-shadow 0.22s ease;
}
.blog-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-lg); }
.blog-card-img {
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: #c8dbc8;
  flex: none;
}
.blog-card-img img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.45s ease; }
.blog-card:hover .blog-card-img img { transform: scale(1.07); }
.blog-card-body { padding: 18px 20px 22px; flex: 1; display: flex; flex-direction: column; }
.blog-cat-badge {
  display: inline-flex;
  background: var(--green-light);
  color: var(--green);
  border-radius: 999px;
  padding: 4px 12px;
  font-size: 11.5px;
  font-weight: 700;
  margin-bottom: 10px;
  align-self: flex-start;
}
.blog-card h3 { margin: 0 0 8px; font-size: 16px; font-weight: 700; color: var(--ink); line-height: 1.3; }
.blog-card p  { margin: 0 0 14px; color: var(--muted); font-size: 13.5px; line-height: 1.5; flex: 1; }
.blog-card-meta { font-size: 12px; color: #9aa49c; }

/* Blog post prose */
.blog-post-layout { display: grid; grid-template-columns: 1fr 300px; gap: 48px; align-items: start; }
.blog-prose h2 { font-size: 26px; margin: 36px 0 12px; }
.blog-prose p  { color: var(--muted); line-height: 1.75; margin: 0 0 18px; }
.blog-prose h2:first-child { margin-top: 0; }
.blog-sidebar { position: sticky; top: calc(var(--header) + 20px); }
.blog-sidebar-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 20px;
  margin-bottom: 16px;
}
.blog-sidebar-card h4 { margin: 0 0 14px; font-size: 15px; font-weight: 700; }
.blog-sidebar-link {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 8px 0;
  border-bottom: 1px solid #f0f5f0;
  text-decoration: none;
  color: inherit;
}
.blog-sidebar-link:last-child { border-bottom: 0; }
.blog-sidebar-link img { width: 52px; height: 44px; object-fit: cover; border-radius: 8px; flex: none; }
.blog-sidebar-link span { font-size: 13px; font-weight: 600; color: var(--ink); line-height: 1.3; }
.blog-sidebar-link:hover span { color: var(--green); }

/* Gallery masonry */
.gallery-masonry { columns: 3; gap: 16px; }
.gallery-masonry-item {
  break-inside: avoid;
  margin-bottom: 16px;
  border-radius: 18px;
  overflow: hidden;
  position: relative;
  cursor: pointer;
}
.gallery-masonry-item img { width: 100%; display: block; transition: transform 0.45s ease; }
.gallery-masonry-item:hover img { transform: scale(1.04); }
.gallery-masonry-item:hover .gallery-item-label { opacity: 1; }
.gallery-masonry-item .gallery-item-label { opacity: 0; transition: opacity 0.25s ease; }

/* Testimonial dark on testimonials page */
.testimonials-hero-dark {
  background: linear-gradient(140deg, #062312 0%, #0f3d20 100%);
  border-radius: 24px;
  padding: 52px 48px;
  color: #fff;
  position: relative;
  overflow: hidden;
  margin-bottom: 32px;
}
.testimonials-hero-dark::before {
  content: "\201C";
  position: absolute;
  top: -10px;
  left: 36px;
  font-size: 180px;
  font-family: var(--font-display);
  color: rgba(30,135,54,0.18);
  line-height: 1;
  pointer-events: none;
}
.testimonials-hero-dark p { font-family: var(--font-display); font-size: 24px; line-height: 1.55; font-style: italic; color: rgba(255,255,255,0.94); margin: 0 0 24px; max-width: 680px; }
.testimonials-hero-dark strong { display: block; font-size: 16px; color: #fff; }
.testimonials-hero-dark span { color: rgba(255,255,255,0.55); font-size: 13px; }

/* Animated counter stats (for inner pages) */
.stats-row { display: flex; gap: 0; background: var(--ink); border-radius: 20px; overflow: hidden; }
.stats-row-item { flex: 1; text-align: center; padding: 28px 16px; border-right: 1px solid rgba(255,255,255,0.08); }
.stats-row-item:last-child { border-right: 0; }
.stats-row-item strong { display: block; font-family: var(--font-display); font-size: 42px; font-weight: 400; color: var(--green-mid); line-height: 1; }
.stats-row-item span { display: block; margin-top: 6px; font-size: 13px; color: rgba(255,255,255,0.55); }

.page-section { padding: 18px 0 56px; }

/* About — owner / Our Story */
.about-story-section { padding: 28px 0 72px; }
.about-story-grid {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  gap: 48px;
  align-items: center;
}
.owner-portrait {
  margin: 0;
  position: relative;
  overflow: hidden;
  border-radius: 24px;
}
.owner-portrait img,
.owner-portrait video {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  object-position: center;
  border-radius: 24px;
  display: block;
  box-shadow: var(--shadow-lg);
  background: #0a1f14;
}
.owner-portrait figcaption {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 18px;
  padding: 14px 16px;
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(6, 35, 18, 0.92), rgba(14, 61, 31, 0.88));
  color: #fff;
  backdrop-filter: blur(6px);
}
.owner-portrait strong {
  display: block;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.owner-portrait span {
  display: block;
  margin-top: 3px;
  font-size: 13px;
  color: rgba(255,255,255,0.7);
}
.about-story-copy h2 {
  margin: 8px 0 14px;
  font-size: 38px;
  letter-spacing: -0.02em;
  line-height: 1.15;
}
.about-story-copy .lede { margin-bottom: 14px; }
.about-story-extra {
  margin: 0 0 26px;
  color: var(--muted);
  font-size: 15.5px;
  line-height: 1.7;
  max-width: 520px;
}

@media (max-width: 900px) {
  .about-story-grid { grid-template-columns: 1fr; gap: 28px; }
  .owner-portrait img,
  .owner-portrait video { max-height: 480px; }
  .about-story-copy h2 { font-size: 30px; }
}

.about-nap {
  display: grid;
  gap: 4px;
  margin: 0 0 22px;
  padding: 14px 16px;
  border-radius: 14px;
  background: #f3f8f0;
  border: 1px solid #dceadc;
  max-width: 440px;
}

/* ── About: What we stand for ── */
.about-values-section {
  position: relative;
  overflow: hidden;
  padding: 72px 0 80px;
}
.about-values-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 80% at 10% 0%, rgba(155, 224, 168, 0.28) 0%, transparent 55%),
    radial-gradient(ellipse 50% 60% at 90% 100%, rgba(30, 135, 54, 0.12) 0%, transparent 50%),
    linear-gradient(180deg, #f4faf2 0%, #e8f3e4 100%);
  pointer-events: none;
}
.about-values-section .wrap { position: relative; z-index: 1; }
.about-values-head {
  text-align: center;
  max-width: 560px;
  margin: 0 auto 40px;
}
.about-values-head h2 { margin: 8px 0 12px; }
.about-values-head .lede {
  margin: 0;
  color: var(--muted);
  font-size: 15.5px;
  line-height: 1.65;
}
.about-values-grid {
  display: grid;
  grid-template-columns: 1.15fr 1fr 1fr;
  gap: 18px;
  align-items: stretch;
}
.about-values-grid > .fade-up { height: 100%; display: flex; }
.about-value-card {
  width: 100%;
  height: 100%;
  padding: 28px 26px 26px;
  border-radius: 24px;
  background: #fff;
  border: 1px solid #dceadc;
  box-shadow: 0 12px 32px rgba(14, 35, 24, 0.06);
  display: flex;
  flex-direction: column;
  transition: transform 0.28s var(--ease-spring), box-shadow 0.28s ease, border-color 0.2s ease;
}
.about-value-card:hover {
  transform: translateY(-6px);
