  max-width: 100%;
  background: rgba(10, 22, 14, 0.55);
  display: flex;
  align-items: safe center;
  justify-content: safe center;
  padding:
    max(12px, env(safe-area-inset-top, 0px))
    max(16px, env(safe-area-inset-right, 0px))
    max(12px, env(safe-area-inset-bottom, 0px))
    max(16px, env(safe-area-inset-left, 0px));
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}
.search-overlay {
  background: rgba(8, 28, 16, 0.45);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  align-items: safe center;
  justify-content: safe center;
  padding: 16px;
}
.search-panel {
  width: min(460px, 100%);
  max-width: 100%;
  margin: auto;
  flex: none;
  background: #f7fbf6;
  border: 1px solid #d8e8da;
  border-radius: 18px;
  padding: 14px;
  box-shadow: 0 20px 50px rgba(8, 30, 16, 0.18);
  animation: searchIn 0.25s ease both;
}
@keyframes searchIn {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: none; }
}
.search-panel-top {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}
.search-panel-badge {
  width: 36px;
  height: 36px;
  border-radius: 11px;
  background: #e5f4e8;
  color: var(--green);
  display: grid;
  place-items: center;
  flex: none;
}
.search-panel-badge svg { width: 16px; height: 16px; }
.search-panel-copy {
  flex: 1;
  min-width: 0;
}
.search-panel-copy strong {
  display: block;
  font-size: 14.5px;
  font-weight: 700;
  color: var(--ink);
}
.search-panel-copy span {
  display: block;
  font-size: 12px;
  color: var(--muted);
  margin-top: 1px;
}
.search-panel-close {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 50%;
  background: #eaf3ea;
  color: #3d5a45;
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
  flex: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.search-panel-close:hover {
  background: var(--green);
  color: #fff;
}
.search-field {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 0 12px;
  border: 1.5px solid #cfe3d1;
  border-radius: 12px;
  background: #fff;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.search-field:focus-within {
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(30,135,54,0.12);
}
.search-field-ico {
  color: var(--green);
  display: grid;
  place-items: center;
  flex: none;
}
.search-field-ico svg { width: 15px; height: 15px; }
.search-panel input,
.search-field input {
  width: 100%;
  border: 0;
  outline: none;
  background: transparent;
  padding: 11px 0;
  font-size: 14.5px;
  color: var(--ink);
}
.search-field input::placeholder { color: #8fa396; }
.search-results {
  padding: 8px 0 0;
  max-height: min(40vh, 260px);
  overflow-y: auto;
}
.search-hint,
.search-empty {
  margin: 0;
  padding: 8px 4px;
  font-size: 12.5px;
  color: var(--muted);
  line-height: 1.4;
}
.search-hit {
  display: block;
  padding: 9px 10px;
  border-radius: 10px;
  text-decoration: none;
  color: inherit;
  transition: background 0.15s ease;
}
.search-hit:hover {
  background: #e5f4e8;
}
.search-hit strong {
  display: block;
  font-size: 14px;
  color: var(--ink);
  margin-bottom: 1px;
}
.search-hit:hover strong { color: var(--green); }
.search-hit span {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}
.video-modal {
  width: min(920px, 100%);
  max-width: 100%;
  margin: auto;
  flex: none;
  background: #0d1c14;
  border-radius: 20px;
  padding: 12px;
  box-shadow: 0 30px 80px rgba(0,0,0,0.25);
}
.video-modal video { width: 100%; border-radius: 12px; max-height: 72vh; background: #000; }
.modal-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; color: #fff; }
.modal-top button {
  border: 0;
  background: transparent;
  cursor: pointer;
  font-size: 14px;
  font-weight: 700;
  color: #fff;
}
.drawer {
  position: fixed;
  inset: 0 0 0 auto;
  width: min(300px, 82vw);
  max-width: 100%;
  background: #fff;
  z-index: 70;
  padding: 14px 14px 24px;
  box-shadow: -16px 0 40px rgba(0,0,0,0.14);
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  border-radius: 16px 0 0 16px;
}
.drawer-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  padding-bottom: 10px;
  border-bottom: 1px solid #e8eee8;
}
.drawer-head strong {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}
.drawer-head .icon-btn {
  width: 32px;
  height: 32px;
  font-size: 14px;
}
.drawer a,
.drawer button.linkish {
  background: none;
  border: 0;
  text-align: left;
  padding: 9px 8px;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--ink);
  cursor: pointer;
  border-radius: 10px;
  text-decoration: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.drawer > a:hover,
.drawer-acc-row a:hover {
  background: #f0f7f1;
  color: var(--green);
}
.drawer-cta {
  margin-top: 12px !important;
  width: 100%;
  justify-content: center;
  padding: 10px 14px !important;
  font-size: 13px !important;
  border-radius: 999px;
}
.backdrop { position: fixed; inset: 0; background: rgba(8,18,12,0.4); z-index: 65; }

@media (max-width: 1080px) {
  .features { grid-template-columns: 1fr 1fr; width: min(720px, calc(100% - 40px)); }
  .service-grid, .service-grid.wide { grid-template-columns: 1fr 1fr; }
  .service-grid > .fade-up { display: contents; }
  .footer-grid, .t-grid { grid-template-columns: 1fr 1fr; }
  .about-grid, .pair-grid, .split, .service-detail { grid-template-columns: 1fr; }
  .service-detail img { width: 100%; height: 200px; }
}

@media (max-width: 820px) {
  .nav, .header .btn { display: none; }
  .header-phone { display: none; }
  .menu-btn { display: grid !important; }
  .brand-logo-header { height: 52px; width: auto; max-width: min(250px, 68vw); min-width: 0; }
  :root { --header: 72px; }
  .header { height: 72px; }
  .brand-logo-footer-wrap { padding: 14px 16px; border-radius: 14px; }
  .brand-logo-footer { height: 60px; width: auto; max-width: 270px; min-width: 0; }
  .home-hero {
    min-height: calc(100svh - var(--header));
    align-items: flex-end;
  }
  .home-hero-copy::before {
    left: -6%;
    top: -8%;
    width: 100%;
    height: 110%;
    background: radial-gradient(
      ellipse at 40% 70%,
      rgba(2, 18, 10, 0.5) 0%,
      transparent 70%
    );
  }
  .home-hero-video,
  .home-hero-poster {
    object-position: center 30%;
  }
  .home-hero-veil {
    background:
      linear-gradient(
        180deg,
        rgba(2, 12, 7, 0.22) 0%,
        rgba(2, 12, 7, 0.08) 28%,
        rgba(2, 12, 7, 0.45) 62%,
        rgba(1, 10, 6, 0.82) 100%
      ),
      linear-gradient(
        90deg,
        rgba(2, 14, 8, 0.35) 0%,
        transparent 55%
      );
  }
  .home-hero-frame {
    width: min(100%, calc(100% - 36px));
    padding: 36px 0 78px;
  }
  .home-hero-copy { max-width: 100%; }
  .home-hero-brand {
    font-size: clamp(24px, 7vw, 32px);
  }
  .home-hero-rule { margin: 14px 0 16px; }
  .home-hero-title,
  .home-hero h1 {
    font-size: clamp(30px, 7.8vw, 42px);
    max-width: 100%;
    margin-bottom: 14px;
  }
  .home-hero-lede {
    font-size: 14.5px;
    margin-bottom: 24px;
    max-width: 100%;
  }
  .home-hero-actions {
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
  }
  .home-hero-cta {
    padding: 12px 18px;
    font-size: 13.5px;
  }
  .home-hero .play { width: 44px; height: 44px; }
  .home-hero-scroll { bottom: 18px; }
  .home-hero-scroll-line { height: 32px; }
  .features { margin-top: -36px; width: calc(100% - 32px); grid-template-columns: 1fr; gap: 12px; }
  .about { padding-top: 36px; }
  .about h2, .why h2, .services h2, .page-hero h1 { font-size: clamp(24px, 5.5vw, 30px); }
  .btn { padding: 10px 16px; font-size: 13px; }
  .about, .about-grid, .about-grid > div { min-width: 0; max-width: 100%; }
  .stats {
    display: flex;
    justify-content: space-between;
    gap: 8px;
    width: 100%;
    max-width: 100%;
  }
  .stat { flex: 1 1 0; width: 0; min-width: 0; max-width: 33%; }
  .stat img { width: 56px; height: 56px; }
  .stat span { font-size: 11px; line-height: 1.25; overflow-wrap: anywhere; }
  .video-card { aspect-ratio: 16 / 10; min-height: 0; }
  .collage { aspect-ratio: 1 / 0.92; grid-template-columns: 0.9fr 1fr; }
  .c-leaf { height: auto !important; }
  .green-card {
    top: 42px;
    padding: 16px 14px;
    border-radius: 16px;
  }
  .green-card h3 { font-size: 22px; }
  .green-card p { font-size: 12.5px; max-width: none; }
  .why-copy h2 { font-size: 30px; }
  .why-copy .reasons, .reasons { grid-template-columns: 1fr; gap: 14px; }
  .why-copy .reason, .reason { display: flex; text-align: left; align-items: center; gap: 12px; }
  .why-copy .reason + .reason::before { display: none; }
  .why-copy .reason img, .reason img { margin: 0; width: 52px; height: 52px; }
  .service-grid, .service-grid.wide, .work-grid, .quote-grid, .t-grid, .footer-grid { grid-template-columns: 1fr; }
  .cta { flex-direction: column; align-items: flex-start; padding: 26px 20px; }
  .cta-bleed { padding: 40px 0; margin-top: 40px; }
  .cta-bleed-inner { flex-direction: column; align-items: flex-start; width: calc(100% - 40px); }
  .cta-bleed h2 { font-size: 28px; }
  .wrap { width: min(var(--wrap), calc(100% - 28px)); }
  .wrap-wide { width: min(1440px, calc(100% - 24px)); }
  .audience-head h2 { font-size: 32px; }
  .audience-card-v2 { min-height: 360px; }
  .audience-card-body h3 { font-size: 24px; }
  .green-card h3 { font-size: 34px; }
}

/* Psychology / conversion sections */
.trust-bar {
  padding: 0 0 36px;
  margin-top: -52px;
  position: relative;
  z-index: 5;
}
.trust-bar-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 22px 8px;
  box-shadow: var(--shadow-lg);
}
.trust-item {
  text-align: center;
  padding: 6px 12px;
  border-right: 1px solid #e4ede4;
}
.trust-item:last-child { border-right: 0; }
.trust-item strong {
  display: block;
  font-family: var(--font-display);
  font-size: 30px;
  color: var(--green);
  font-weight: 400;
  line-height: 1.1;
}
.trust-item span {
  display: block;
  margin-top: 4px;
  font-size: 12.5px;
  color: var(--muted);
  line-height: 1.35;
}

.psy-section { padding: 64px 0; }
.psy-muted { background: #edf5e9; }
.psy-head { max-width: 620px; margin-bottom: 26px; }
.psy-head.row {
  max-width: none;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
}
.psy-head h2 {
  margin: 8px 0 10px;
  font-size: 34px;
  line-height: 1.15;
}
.psy-head .lede { margin: 0; color: var(--muted); }

.audience-grid,
.pain-grid,
.promise-grid,
.process-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
.audience-section {
  padding: 72px 0 88px;
  background: linear-gradient(180deg, #eaf4e6 0%, #f3f8f0 72%);
}
.audience-head {
  text-align: center;
  max-width: 720px;
  margin: 0 auto 40px;
}
.audience-head h2 { font-size: 44px; letter-spacing: -0.02em; }
.audience-head .lede {
  margin-top: 12px;
  font-size: 17px;
  line-height: 1.6;
  color: var(--muted);
}
.audience-grid { gap: 20px; }
.audience-grid > .fade-up.fill,
.svc-extras-grid > .fade-up.fill {
  height: 100%;
  display: flex;
}
.audience-grid > .fade-up.fill > a,
.svc-extras-grid > .fade-up.fill > a,
.svc-extras-grid > .svc-extra-card {
  height: 100%;
  width: 100%;
}
.services-hub-grid-v2 > .svc-hub-card {
  height: 100%;
}
.pain-grid, .promise-grid { grid-template-columns: repeat(3, 1fr); }

.audience-card,
.pain-card,
.promise-card,
.process-card {
  background: #fff;
  border: 1px solid #dceadc;
  border-radius: 18px;
  padding: 22px 18px;
  box-shadow: var(--shadow-sm);
  transition: transform 0.22s var(--ease-spring), box-shadow 0.22s ease;
}
.audience-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 164px;
}
.audience-card:hover, .pain-card:hover, .promise-card:hover, .process-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.audience-card h3,
.pain-card h3,
.promise-card h3,
.process-card h3 {
  margin: 0;
  font-family: var(--font-body);
  font-size: 16px;
  font-weight: 700;
  color: var(--ink);
}
.audience-card p,
.pain-card p,
.promise-card p,
.process-card p {
  margin: 0;
  color: var(--muted);
  font-size: 13.5px;
  line-height: 1.45;
  flex: 1;
}
.audience-card span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--green);
  font-size: 13.5px;
  font-weight: 650;
  margin-top: auto;
}

.process-step {
  display: inline-block;
  font-family: var(--font-display);
  font-size: 22px;
  color: #3e8b32;
  margin-bottom: 8px;
}

.projects-teaser {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.projects-teaser figure,
.gallery-figure {
  margin: 0;
  border-radius: 14px;
  overflow: hidden;
  background: #d7e2d4;
}
.projects-teaser img,
.gallery-figure img {
  width: 100%;
  height: 200px;
  object-fit: cover;
}
.gallery-figure figcaption {
  padding: 8px 10px 10px;
  font-size: 12.5px;
  color: var(--muted);
  background: #fff;
}

.areas-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.area-chip {
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 999px;
  padding: 10px 16px;
  font-size: 13.5px;
  font-weight: 650;
  color: var(--green-deep);
}
.area-chip:hover { border-color: #b7d4b0; color: var(--green); }

.promise-section {
  background: linear-gradient(160deg, #f0f8ec 0%, #e2f0dc 100%);
  border-top: 1px solid #d8ead4;
}
.process-step {
  display: inline-block;
  font-family: var(--font-display);
  font-size: 24px;
  color: var(--green);
  margin-bottom: 10px;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--green-light);
  display: grid;
  place-items: center;
  font-size: 16px;
  font-weight: 700;
  font-family: var(--font-body);
  letter-spacing: 0;
  margin-bottom: 12px;
}

.mid-cta { padding: 12px 0 10px; }
.mid-cta-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  background: linear-gradient(135deg, #0a2e18 0%, #16522a 100%);
  color: #fff;
  border-radius: 24px;
  padding: 36px 40px;
  box-shadow: 0 12px 40px rgba(14,35,24,0.20);
}
.mid-cta h2 { margin: 0 0 8px; font-size: 30px; color: #fff; }
.mid-cta p { margin: 0; color: rgba(255,255,255,0.72); max-width: 460px; font-size: 15px; }
.mid-cta-actions { display: flex; flex-wrap: wrap; gap: 12px; }

.quote-layout {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 28px;
  align-items: start;
}
.quote-aside {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 22px 20px;
}
.quote-aside h2 { margin: 0 0 14px; font-size: 26px; }
.quote-aside h3 {
  margin: 22px 0 10px;
  font-family: var(--font-body);
  font-size: 15px;
  font-weight: 700;
}
.quote-steps {
  margin: 0;
  padding-left: 18px;
  display: grid;
  gap: 12px;
}
.quote-steps li { color: var(--muted); }
.quote-steps strong {
  display: block;
  color: var(--ink);
  margin-bottom: 2px;
}
.assure-list {
  margin: 0;
  padding-left: 18px;
  color: var(--muted);
  display: grid;
  gap: 6px;
  font-size: 14px;
}

@media (max-width: 980px) {
  .trust-bar-grid {
    grid-template-columns: repeat(4, 1fr);
    padding: 16px 4px;
  }
  .trust-item strong { font-size: 24px; }
  .trust-item span { font-size: 11px; }
  .audience-grid,
  .process-grid,
  .projects-teaser { grid-template-columns: 1fr 1fr; }
  .pain-grid,
  .promise-grid,
  .quote-layout { grid-template-columns: 1fr; }
  .psy-head.row { flex-direction: column; align-items: flex-start; }
  .mid-cta-inner { flex-direction: column; align-items: flex-start; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .stat-block:nth-child(2) { border-right: 0; }
  .stat-block:nth-child(3) { border-top: 1px solid rgba(255,255,255,0.10); border-right: 0; grid-column: 1 / -1; }
  .cta { padding: 32px 28px; }
  .cta h2 { font-size: 26px; }
}

@media (max-width: 640px) {
  .trust-bar-grid {
    grid-template-columns: repeat(4, 1fr);
    padding: 14px 2px;
    border-radius: 16px;
  }
  .trust-item {
    padding: 4px 4px;
    border-right: 1px solid #e4ede4;
    border-bottom: 0;
  }
  .trust-item:last-child { border-right: 0; }
  .trust-item strong { font-size: 20px; }
  .trust-item span { font-size: 9.5px; line-height: 1.25; }
  .audience-grid,
  .process-grid,
  .projects-teaser,
  .pain-grid,
  .promise-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr; }
  .stat-block { border-right: 0; border-bottom: 1px solid rgba(255,255,255,0.10); }
  .stat-block:last-child { border-bottom: 0; }
  .hero h1 { font-size: 44px; }
  .mid-cta-inner { padding: 28px 22px; }
}
.breadcrumbs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
  font-size: 12.5px;
  color: #7d8a83;
  margin-bottom: 14px;
}
.breadcrumbs a { color: #3e8b32; }
.bc-sep { margin: 0 4px; color: #c0cbc3; }
.seo-prose { max-width: 760px; }
.seo-prose h2 { font-size: 28px; margin: 28px 0 10px; }
.seo-prose p, .seo-prose li { color: var(--muted); line-height: 1.65; }
.seo-prose ul { padding-left: 18px; }
.seo-link-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  margin-top: 14px;
}
.seo-link-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 16px;
  box-shadow: 0 4px 16px rgba(20, 70, 35, 0.04);
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}
.seo-link-card:hover {
  transform: translateY(-2px);
  border-color: var(--green);
  box-shadow: var(--shadow);
}
.seo-link-card strong { color: var(--ink); font-size: 14.5px; }
.seo-link-card span, .seo-link-card em { color: var(--muted); font-size: 13px; font-style: normal; }

.geo-state-stack { margin-top: 28px; display: grid; gap: 22px; }
.geo-state-block h3 {
  margin: 0 0 10px;
  font-size: 18px;
