.promise-card-v2 h3 { margin: 0 0 8px; font-size: 17px; font-weight: 700; color: var(--ink); }
.promise-card-v2 p  { margin: 0; color: var(--muted); font-size: 14px; line-height: 1.6; }

/* ── Services hub v2 ── */
.svc-page-motion .fade-up {
  opacity: 1;
  transform: none;
}
.svc-page-hero .eyebrow,
.svc-page-hero h1,
.svc-page-hero p,
.svc-page-hero .hero-cta-row {
  animation: none;
}
.svc-page-motion .audience-card-v2,
.svc-page-motion .svc-hub-card,
.svc-page-motion .svc-extra-card,
.svc-page-motion .process-step-wrap,
.svc-page-motion .promise-card-v2,
.svc-page-motion .t-card,
.svc-page-motion .faq-item {
  will-change: transform, opacity;
}

/* Core services — desktop editorial bento */
.core-services-section {
  padding: 72px 0 80px;
  background: linear-gradient(180deg, #f7fbf5 0%, #edf5e9 100%);
}
.core-services-head {
  margin-bottom: 36px !important;
  align-items: flex-end;
}
.core-services-head h2 {
  font-size: 42px;
  letter-spacing: -0.02em;
}
.core-services-head p {
  margin: 10px 0 0;
  max-width: 420px;
  color: var(--muted);
  font-size: 15.5px;
  line-height: 1.6;
}
.services-hub-grid-v2 {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 18px;
  align-items: stretch;
}
.services-hub-grid-v2 > .svc-hub-card {
  height: 100%;
  min-width: 0;
}
.services-hub-grid-v2 > .svc-hub-card.is-featured {
  grid-column: 1 / -1;
  grid-row: auto;
}
.services-hub-grid-v2 > .svc-hub-card:not(.is-featured) {
  grid-column: span 4;
}

.svc-hub-card {
  background: linear-gradient(180deg, #ffffff 0%, #f7fbf6 100%);
  border: 1px solid rgba(201, 221, 207, 0.9);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  text-decoration: none;
  box-shadow: var(--shadow-sm);
  transition: transform 0.28s var(--ease-spring), box-shadow 0.28s ease, border-color 0.2s ease;
}
.svc-hub-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-lg);
  border-color: #a8c9b0;
}
.svc-hub-img {
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: #0a1f14;
  position: relative;
}
.svc-hub-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.6s ease;
}
.svc-hub-num {
  display: grid;
  place-items: center;
  position: absolute;
  left: 14px;
  bottom: 14px;
  min-width: 36px;
  height: 36px;
  padding: 0 8px;
  border-radius: 10px;
  background: rgba(6, 35, 18, 0.82);
  color: #9be0a8;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.06em;
  z-index: 1;
  backdrop-filter: blur(6px);
}
.svc-hub-card:hover .svc-hub-img img { transform: scale(1.06); }
.svc-hub-body {
  padding: 20px 22px 22px;
  flex: 1;
  display: flex;
  flex-direction: column;
}
.svc-hub-body h3 {
  margin: 0 0 8px;
  font-size: 18px;
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.01em;
  line-height: 1.25;
}
.svc-hub-body p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.5;
  flex: 1;
}
.svc-hub-kicker {
  display: none;
}
.svc-hub-points {
  display: none;
  list-style: none;
  margin: 0;
  padding: 0;
}
.svc-hub-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  color: var(--green);
  font-size: 13px;
  font-weight: 700;
  transition: gap 0.2s ease;
}
.svc-hub-card:hover .svc-hub-link { gap: 10px; }

/* Featured first card — full-width, dense split (desktop) */
@media (min-width: 641px) {
  .svc-hub-card.is-featured {
    flex-direction: row;
    align-items: stretch;
    min-height: 292px;
    background:
      linear-gradient(118deg, #ffffff 0%, #f3f9ef 55%, #eef6ea 100%);
  }
  .svc-hub-card.is-featured .svc-hub-img {
    flex: 0 0 40%;
    width: 40%;
    aspect-ratio: auto;
    min-height: 100%;
    align-self: stretch;
  }
  .svc-hub-card.is-featured .svc-hub-body {
    flex: 1;
    padding: 26px 28px 24px 26px;
    justify-content: flex-start;
    gap: 14px;
  }
  .svc-hub-card.is-featured .svc-hub-kicker {
    display: inline-flex;
    align-self: flex-start;
    margin: 0;
    padding: 5px 11px;
    border-radius: 999px;
    background: rgba(30, 135, 54, 0.12);
    color: var(--green);
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }
  .svc-hub-featured-main {
    display: grid;
    grid-template-columns: minmax(0, 1.15fr) minmax(168px, 0.85fr);
    gap: 22px;
    flex: 1;
    align-items: stretch;
    min-height: 0;
  }
  .svc-hub-featured-copy {
    display: flex;
    flex-direction: column;
    min-width: 0;
  }
  .svc-hub-card.is-featured .svc-hub-body h3 {
    font-size: 28px;
    font-family: var(--font-display);
    font-weight: 400;
    letter-spacing: -0.02em;
    margin: 0 0 10px;
    line-height: 1.15;
  }
  .svc-hub-card.is-featured .svc-hub-body p {
    flex: none;
    font-size: 14.5px;
    line-height: 1.55;
    margin: 0 0 18px;
    max-width: none;
  }
  .svc-hub-card.is-featured .svc-hub-points {
    display: flex;
    flex-direction: column;
    justify-content: stretch;
    gap: 10px;
    margin: 0;
    padding: 2px 0 2px 18px;
    border-left: 1px solid #d4e5ce;
  }
  .svc-hub-card.is-featured .svc-hub-points li {
    position: relative;
    flex: 1;
    display: flex;
    align-items: center;
    padding: 12px 14px 12px 34px;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.78);
    border: 1px solid #dcead6;
    font-size: 13px;
    font-weight: 600;
    color: #2a4033;
    line-height: 1.3;
  }
  .svc-hub-card.is-featured .svc-hub-points li::before {
    content: "";
    position: absolute;
    left: 14px;
    top: 50%;
    transform: translateY(-50%);
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--green);
    box-shadow: 0 0 0 4px rgba(30, 135, 54, 0.12);
  }
  .svc-hub-card.is-featured .svc-hub-link {
    margin-top: auto;
    align-self: flex-start;
    padding: 10px 16px;
    border-radius: 999px;
    background: var(--green);
    color: #fff;
  }
  .svc-hub-card.is-featured:hover .svc-hub-link {
    background: #0c6b2e;
  }
  .svc-hub-card.is-featured .svc-hub-num {
    left: 18px;
    bottom: 18px;
    min-width: 42px;
    height: 42px;
    font-size: 13px;
    border-radius: 12px;
  }
}

@media (min-width: 641px) and (max-width: 900px) {
  .svc-hub-featured-main {
    grid-template-columns: 1fr;
    gap: 14px;
  }
  .svc-hub-card.is-featured .svc-hub-points {
    flex-direction: row;
    flex-wrap: wrap;
    padding: 0;
    border-left: 0;
  }
  .svc-hub-card.is-featured .svc-hub-points li {
    flex: 1 1 140px;
  }
  .svc-hub-card.is-featured .svc-hub-img {
    flex: 0 0 36%;
    width: 36%;
  }
  .svc-hub-card.is-featured .svc-hub-body h3 {
    font-size: 24px;
  }
}

.audience-swipe-hint {
  display: none;
}

@media (max-width: 900px) {
  .services-hub-grid-v2 > .svc-hub-card:not(.is-featured) {
    grid-column: span 6;
  }
}
.svc-extras-section { padding: 28px 0 80px; }
.svc-extras-head {
  display: block;
  margin-bottom: 32px;
  max-width: 720px;
}
.svc-extras-head h2 { font-size: 40px; letter-spacing: -0.02em; }
.svc-extras-head p {
  margin: 12px 0 0;
  max-width: 640px;
  color: var(--muted);
  font-size: 16px;
  line-height: 1.6;
}
.svc-extras-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.svc-extra-card {
  background: #fff;
  border: 1px solid #e0ece0;
  border-radius: 22px;
  padding: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  text-decoration: none;
  box-shadow: var(--shadow-sm);
  transition: transform 0.25s var(--ease-spring), box-shadow 0.25s ease, border-color 0.18s ease;
}
.svc-extra-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
  border-color: #c5dfc4;
  background: #fff;
}
.svc-extra-img {
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: #c8dbc8;
}
.svc-extra-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: 0;
  transition: transform 0.5s ease;
}
.svc-extra-card:hover .svc-extra-img img { transform: scale(1.06); }
.svc-extra-body {
  padding: 20px 22px 22px;
  display: flex;
  flex-direction: column;
  flex: 1;
}
.svc-extra-card h3 {
  margin: 0 0 8px;
  font-size: 18px;
  font-weight: 700;
  color: var(--ink);
  font-family: var(--font-display);
}
.svc-extra-card p {
  margin: 0;
  font-size: 13.5px;
  line-height: 1.5;
  color: var(--muted);
  flex: 1;
}
.svc-extra-card .svc-hub-link { margin-top: 16px; }
.svc-extra-arrow { flex: none; color: #b0c4b0; transition: color 0.18s ease, transform 0.18s ease; }
.svc-extra-card:hover .svc-extra-arrow { color: var(--green); transform: translateX(3px); }

/* ── Gallery editorial grid ── */
.gallery-editorial {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-auto-rows: 220px;
  gap: 12px;
}
.ge-item {
  border-radius: 18px;
  overflow: hidden;
  position: relative;
  background: #c8dbc8;
  cursor: pointer;
}
.ge-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.45s ease;
}
.ge-item:hover img { transform: scale(1.06); }
.ge-item:hover .gallery-item-label { opacity: 1; }
.ge-item .gallery-item-label { opacity: 0; transition: opacity 0.25s ease; }

/* Specific sizes */
.ge-large  { grid-column: span 2; grid-row: span 2; }
.ge-tall   { grid-row: span 2; }
.ge-wide   { grid-column: span 2; }
.ge-normal { /* default 1×1 */ }

/* ═══════════════════════════════════════════
   NEW EDITORIAL HOMEPAGE COMPONENTS
   ═══════════════════════════════════════════ */

/* -- Hero shortcuts (floating cards at hero bottom) -- */
.hero-shortcuts {
  position: absolute;
  bottom: -18px;
  left: 64px;
  z-index: 4;
  display: flex;
  gap: 12px;
  animation: fadeUp 0.75s var(--ease-spring) both 0.75s;
}
.hero-sc {
  background: rgba(255,255,255,0.97);
  border-radius: 18px;
  padding: 10px 16px 10px 10px;
  display: flex;
  align-items: center;
  gap: 10px;
  box-shadow: 0 12px 32px rgba(0,0,0,0.18);
  min-width: 172px;
  text-decoration: none;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.hero-sc:hover { transform: translateY(-3px); box-shadow: 0 18px 40px rgba(0,0,0,0.22); }
.hero-sc img { width: 46px; height: 46px; border-radius: 12px; object-fit: cover; flex: none; }
.hero-sc-text strong { display: block; font-size: 13px; font-weight: 700; color: var(--ink); line-height: 1.2; }
.hero-sc-text span  { display: block; font-size: 11.5px; color: var(--muted); margin-top: 2px; }

/* -- Section header row (heading left + link right) -- */
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 32px;
}
.section-header h2 { margin: 6px 0 0; }

/* -- About: flip order + feature tags -- */
.about-grid-new {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 48px;
  align-items: center;
}
.about-tags { display: flex; flex-wrap: wrap; gap: 8px; margin: 20px 0 28px; }
.about-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--green-light);
  color: var(--green);
  border-radius: 999px;
  padding: 6px 14px;
  font-size: 13px;
  font-weight: 650;
}
.about-tag::before { content: "✓"; font-weight: 700; }

/* -- Services: Asymmetric (big card + list) -- */
.services-layout {
  display: grid;
  grid-template-columns: 1.25fr 1fr;
  gap: 20px;
  align-items: start;
}
.service-hero-card {
  position: relative;
  border-radius: 24px;
  overflow: hidden;
  min-height: 500px;
  display: block;
  text-decoration: none;
  cursor: pointer;
}
.service-hero-card > img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.55s ease;
  display: block;
}
.service-hero-card:hover > img { transform: scale(1.06); }
.service-hero-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(5,18,10,0.88) 0%, rgba(5,18,10,0.30) 45%, rgba(5,18,10,0.04) 70%);
}
.service-hero-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1;
  padding: 28px;
  color: #fff;
}
.service-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: rgba(30,135,54,0.75);
  backdrop-filter: blur(6px);
  border-radius: 999px;
  padding: 5px 12px 5px 8px;
  font-size: 12px;
  font-weight: 700;
  color: #fff;
  margin-bottom: 12px;
}
.service-hero-overlay h3 {
  margin: 0 0 8px;
  font-size: 28px;
  font-family: var(--font-display);
  line-height: 1.15;
}
.service-hero-overlay p { margin: 0 0 20px; font-size: 14.5px; color: rgba(255,255,255,0.80); line-height: 1.55; }

.service-list { display: flex; flex-direction: column; gap: 11px; }
.service-list > .fade-up { display: block; }
.service-list-item {
  background: #fff;
  border: 1px solid #dceadc;
  border-radius: 16px;
  padding: 16px 18px;
  display: flex;
  align-items: center;
  gap: 14px;
  text-decoration: none;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}
.service-list-item:hover {
  transform: translateX(5px);
  box-shadow: var(--shadow);
  border-color: var(--green);
  background: #fafff8;
}
.service-list-badge {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--green-light);
  color: var(--green);
  display: grid;
  place-items: center;
  flex: none;
  transition: background 0.18s ease;
}
.service-list-item:hover .service-list-badge { background: var(--green); color: #fff; }
.service-list-text { flex: 1; min-width: 0; }
.service-list-text strong { display: block; font-size: 14px; font-weight: 700; color: var(--ink); line-height: 1.2; }
.service-list-text span  { display: block; font-size: 12.5px; color: var(--muted); margin-top: 2px; }
.service-list-arrow { color: #b0c4b0; flex: none; transition: color 0.18s ease, transform 0.18s ease; }
.service-list-item:hover .service-list-arrow { color: var(--green); transform: translateX(3px); }

/* -- Gallery: infinite marquee -- */
.gallery-section { padding: 72px 0 0; }

@keyframes marqueeScroll {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

.gallery-marquee-wrap {
  margin-top: 28px;
  overflow: hidden;
  position: relative;
}
.gallery-marquee-wrap::before,
.gallery-marquee-wrap::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 16px;
  width: 120px;
  z-index: 2;
  pointer-events: none;
}
.gallery-marquee-wrap::before { left: 0; background: linear-gradient(90deg, var(--bg) 0%, transparent 100%); }
.gallery-marquee-wrap::after  { right: 0; background: linear-gradient(-90deg, var(--bg) 0%, transparent 100%); }

.gallery-marquee {
  display: flex;
  gap: 16px;
  width: max-content;
  animation: marqueeScroll 32s linear infinite;
  padding-bottom: 16px;
}
.gallery-marquee:hover { animation-play-state: paused; }

.gallery-marquee-item {
  flex: none;
  width: 340px;
  height: 250px;
  border-radius: 20px;
  overflow: hidden;
  position: relative;
  display: block;
  text-decoration: none;
}
.gallery-marquee-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.45s ease;
}
.gallery-marquee-item:hover img { transform: scale(1.07); }
.gallery-item-label {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(0deg, rgba(5,18,10,0.80) 0%, transparent 65%);
  color: #fff;
  padding: 30px 16px 14px;
  font-size: 13.5px;
  font-weight: 650;
}

/* Keep old strip classes for gallery/inner pages */
.gallery-strip-outer { overflow: hidden; }
.gallery-strip { display: flex; gap: 16px; overflow-x: auto; scrollbar-width: none; padding-bottom: 8px; }
.gallery-strip::-webkit-scrollbar { display: none; }
.gallery-strip-item { flex: none; border-radius: 20px; overflow: hidden; position: relative; }
.gallery-strip-item img { width: 340px; height: 260px; object-fit: cover; display: block; transition: transform 0.4s ease; }
.gallery-strip-item:hover img { transform: scale(1.07); }

/* -- Process: Horizontal timeline -- */
.process-head {
  text-align: center;
  max-width: 480px;
  margin: 0 auto 52px;
}
.process-timeline {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  position: relative;
  gap: 0;
}
.process-timeline-5 {
  grid-template-columns: repeat(5, 1fr);
}
.process-timeline-5 .process-line {
  left: 10%;
  right: 10%;
}
.process-timeline::before {
  content: none;
}
.process-line {
  position: absolute;
  top: 26px;
  left: 12.5%;
  right: 12.5%;
  height: 2px;
  background: linear-gradient(90deg, transparent 0%, var(--green) 15%, var(--green) 85%, transparent 100%);
  z-index: 0;
  pointer-events: none;
  transform: scaleX(0);
  transform-origin: left center;
}
.process-timeline > .fade-up { display: contents; }
.process-step-wrap {
  text-align: center;
  padding: 0 20px 0;
  position: relative;
  z-index: 1;
}
.process-num {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--green);
  color: #fff;
  font-size: 16px;
  font-weight: 700;
  display: grid;
  place-items: center;
  margin: 0 auto 20px;
  position: relative;
  z-index: 1;
  box-shadow: 0 0 0 8px #daf0df;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.process-step-wrap:hover .process-num {
  transform: scale(1.12);
  box-shadow: 0 0 0 12px #c8eacf, 0 6px 20px rgba(30,135,54,0.3);
}
.process-step-wrap h3 { font-size: 15px; font-weight: 700; margin: 0 0 8px; color: var(--ink); }
.process-step-wrap p  { font-size: 13.5px; color: var(--muted); line-height: 1.55; margin: 0; }

/* -- Testimonials: dark featured -- */
.testimonial-section { padding: 64px 0; }
.testimonial-dark {
  background: linear-gradient(140deg, #062312 0%, #0e3d1f 55%, #051a0e 100%);
  border-radius: 28px;
  padding: 56px 52px 44px;
  color: #fff;
  position: relative;
  overflow: hidden;
  text-align: center;
}
.testimonial-dark::before {
  content: "\201C";
  position: absolute;
  top: -20px;
  left: 36px;
  font-size: 200px;
  font-family: var(--font-display);
  color: rgba(30,135,54,0.18);
  line-height: 1;
  pointer-events: none;
  user-select: none;
}
.testimonial-dark::after {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(30,135,54,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.testimonial-dark-text {
  font-family: var(--font-display);
  font-size: 26px;
  line-height: 1.55;
  color: rgba(255,255,255,0.96);
  max-width: 720px;
  margin: 0 auto 32px;
  position: relative;
  z-index: 1;
  font-style: italic;
}
.testimonial-dark-author { margin-bottom: 36px; }
.testimonial-dark-author strong { display: block; font-size: 16px; color: #fff; font-weight: 700; }
.testimonial-dark-author span  { display: block; font-size: 13px; color: rgba(255,255,255,0.55); margin-top: 3px; }
.testimonial-mini-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  text-align: left;
}
.testimonial-mini {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.09);
  border-radius: 18px;
  padding: 20px;
  position: relative;
  transition: background 0.2s ease;
}
.testimonial-mini:hover { background: rgba(255,255,255,0.10); }
.testimonial-mini p { font-size: 14px; color: rgba(255,255,255,0.80); margin: 0 0 14px; line-height: 1.6; font-style: italic; }
.testimonial-mini strong { display: block; font-size: 13.5px; color: #fff; font-weight: 700; }
.testimonial-mini span   { display: block; font-size: 12px; color: rgba(255,255,255,0.5); margin-top: 2px; }

/* ── LEAD CAPTURE SECTION ── */
.lead-section { padding: 72px 0; background: linear-gradient(160deg, #f0f8ec 0%, #e4f2e0 100%); }
.lead-section-footer {
  margin-top: 8px;
  padding: 80px 0 88px;
  border-top: 1px solid #d8ead4;
}
.lead-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: center;
}
.lead-visual {
  position: relative;
  border-radius: 24px;
  overflow: hidden;
}
.lead-visual > img:first-child {
  width: 100%;
  aspect-ratio: 4 / 5;
  object-fit: cover;
  border-radius: 24px;
  display: block;
  box-shadow: var(--shadow-lg);
}
.lead-visual-2 {
  position: absolute;
  bottom: -24px;
  right: -24px;
  width: 52%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: 18px;
  border: 4px solid var(--bg-2);
  box-shadow: var(--shadow-lg);
}
.lead-visual-tag {
  position: absolute;
  top: 24px;
  left: 24px;
  background: rgba(255,255,255,0.97);
  border-radius: 16px;
  padding: 14px 18px;
  box-shadow: var(--shadow);
  max-width: 200px;
}
.lead-star { display: block; color: #f4a518; font-size: 14px; letter-spacing: 2px; margin-bottom: 4px; }
.lead-visual-tag strong { display: block; font-size: 13px; font-weight: 700; color: var(--ink); }
.lead-visual-tag span { display: block; font-size: 11.5px; color: var(--muted); margin-top: 2px; }

.lead-content h2 { font-size: 36px; margin: 8px 0 14px; max-width: 480px; }
.lead-content > p { color: var(--muted); font-size: 15px; line-height: 1.65; margin: 0 0 22px; max-width: 420px; }

.lead-trust-row { display: flex; flex-direction: column; gap: 7px; margin-bottom: 28px; }
.lead-trust-item { display: flex; align-items: center; gap: 8px; font-size: 13.5px; color: var(--muted); }
.lead-check { color: var(--green); font-weight: 700; font-size: 15px; }

/* Lead form */
.lead-form { display: flex; flex-direction: column; gap: 10px; }
.lead-field { display: flex; flex-direction: column; gap: 4px; }
.lead-field input,
.lead-field select {
  border: 1.5px solid #d0e4d0;
  border-radius: 12px;
  padding: 13px 14px;
  font-size: 15px;
  background: #fff;
  color: var(--ink);
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  font-family: inherit;
}
.lead-field input:focus,
.lead-field select:focus {
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(30,135,54,0.12);
}
.lead-field input.has-err,
.lead-field select.has-err { border-color: #c0392b; background: #fff8f7; }
.lead-err { font-size: 12px; color: #c0392b; font-weight: 600; }
.lead-err-banner,
.lead-pop-submit-error,
.cm-err-banner {
  padding: 10px 12px;
  border-radius: 12px;
  background: #fdeeee;
  border: 1px solid #f0c7c7;
  font-size: 13px;
  line-height: 1.5;
}
.lead-submit { width: 100%; justify-content: center; font-size: 15px; padding: 13px 20px; margin-top: 4px; }

.lead-success {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 28px 24px;
  text-align: center;
}
.lead-success-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--green-light);
  color: var(--green);
  font-size: 22px;
  font-weight: 700;
  display: grid;
  place-items: center;
  margin: 0 auto 14px;
}
.lead-success h3 { margin: 0 0 8px; font-size: 22px; color: var(--ink); }
.lead-success p { margin: 0; color: var(--muted); font-size: 14.5px; line-height: 1.6; }

/* Responsive for new sections */
