/* ── Full-frame gallery ── */
.gal-page { padding: 16px 0 72px; }
.gal-masonry { column-gap: 16px; }
.gal-cols-3 { columns: 3; }
.gal-cols-4 { columns: 4; }
.gal-cols-2 { columns: 2; }

/* Gallery page — compact even cards */
.gal-page .gal-masonry {
  columns: unset !important;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  align-items: stretch;
}
.gal-page .gal-shot {
  break-inside: avoid;
  margin: 0;
  border-radius: 14px;
  overflow: hidden;
  background: #d7e2d4;
  position: relative;
  display: block;
  text-decoration: none;
  color: inherit;
  box-shadow: var(--shadow-sm);
  transition: transform 0.28s var(--ease-spring), box-shadow 0.28s ease;
  aspect-ratio: 4 / 3;
  max-height: 200px;
  width: 100%;
  min-width: 0;
}
.gal-page .gal-shot img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
  background: #e4eee2;
  transition: transform 0.55s ease;
}
.gal-page .gal-shot:hover img { transform: scale(1.04); }
.gal-page .gal-shot:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.gal-page .gal-shot:hover .gallery-item-label { opacity: 1; }
.gal-page .gal-shot .gallery-item-label { opacity: 0; }

/* Home gallery — compact grid */
.gallery-section .gal-masonry {
  columns: unset !important;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  align-items: stretch;
}
.gallery-section .gal-shot {
  margin: 0;
  border-radius: 12px;
  overflow: hidden;
  background: #d7e2d4;
  position: relative;
  display: block;
  text-decoration: none;
  color: inherit;
  box-shadow: var(--shadow-sm);
  transition: transform 0.28s var(--ease-spring), box-shadow 0.28s ease;
  width: 100%;
  min-width: 0;
  height: 140px;
  aspect-ratio: auto;
  max-height: none;
}
.gallery-section .gal-shot:nth-child(6n + 1),
.gallery-section .gal-shot:nth-child(6n + 2),
.gallery-section .gal-shot:nth-child(6n + 3),
.gallery-section .gal-shot:nth-child(6n + 4),
.gallery-section .gal-shot:nth-child(6n + 5),
.gallery-section .gal-shot:nth-child(6n + 6) {
  aspect-ratio: auto;
  height: 140px;
  max-height: none;
}
.gallery-section .gal-shot img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
  background: #e4eee2;
  transition: transform 0.55s ease;
}
.gallery-section .gal-shot:hover img { transform: scale(1.05); }
.gallery-section .gal-shot:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.gallery-section .gal-shot:hover .gallery-item-label { opacity: 1; }
.gallery-section .gal-shot .gallery-item-label { opacity: 0; }

/* Shared fallback for other gal usages */
.gal-shot {
  break-inside: avoid;
  margin: 0 0 16px;
  border-radius: 18px;
  overflow: hidden;
  background: #d7e2d4;
  position: relative;
  display: block;
  text-decoration: none;
  color: inherit;
  box-shadow: var(--shadow-sm);
  transition: transform 0.28s var(--ease-spring), box-shadow 0.28s ease;
}
.gal-shot img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: contain;
  background: #e4eee2;
  transition: transform 0.55s ease;
}
.gal-shot:hover img { transform: scale(1.04); }
.gal-shot:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.gal-shot:hover .gallery-item-label { opacity: 1; }
.gal-shot .gallery-item-label { opacity: 0; }

/* ── Proof quote + stats (matches testimonial screenshot) ── */
.proof-section { padding: 36px 0 64px; }
.proof-quote {
  background: #0b2a16;
  border-radius: 28px;
  padding: 48px 48px 40px;
  color: #fff;
  margin: 0 0 20px;
  position: relative;
  overflow: hidden;
}
.proof-quote::before {
  content: "\201C";
  position: absolute;
  top: 8px;
  left: 28px;
  font-size: 92px;
  font-family: var(--font-display);
  color: rgba(255,255,255,0.16);
  line-height: 1;
  pointer-events: none;
}
.proof-quote p {
  position: relative;
  z-index: 1;
  font-family: var(--font-display);
  font-size: 26px;
  line-height: 1.5;
  font-style: italic;
  color: rgba(255,255,255,0.96);
  margin: 28px 0 28px;
  max-width: 920px;
}
.proof-quote footer {
  position: relative;
  z-index: 1;
}
.proof-quote strong {
  display: block;
  font-size: 16px;
  font-style: normal;
  font-family: var(--font-body);
}
.proof-quote span {
  display: block;
  margin-top: 4px;
  font-size: 13.5px;
  color: rgba(255,255,255,0.5);
}
.proof-stats {
