.cdl-wa { background: #25D366 !important; color: #fff !important; }
.cdl-mail { background: #1e8736 !important; color: #fff !important; }
.cdl-pin { background: #9be0a8 !important; color: #062312 !important; }
.cdl-clock { background: #fff !important; color: #0e5c28 !important; }
.cdl-phone { background: #fff !important; color: #0e5c28 !important; }
.contact-detail-list em {
