}
.contact-areas-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.contact-areas-chips a {
  background: rgba(255,255,255,0.09);
  border: 1px solid rgba(255,255,255,0.16);
  color: rgba(255,255,255,0.80);
  border-radius: 999px;
