}
.contact-areas-chips a:hover { background: rgba(255,255,255,0.20); color: #fff; }

/* Assurances v2 */
.contact-assures-v2 {
  list-style: none;
  margin: 0;
  padding: 18px 0 0;
  border-top: 1px solid rgba(255,255,255,0.10);
  display: grid;
  gap: 8px;
}
.contact-assures-v2 li {
  display: flex;
  align-items: center;
  gap: 10px;
