  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
}
.contact-faq-head h2 { margin: 6px 0 0; font-size: 30px; }
.contact-faq-grid { display: grid; gap: 10px; }

/* Mobile */
@media (max-width: 900px) {
  .contact-split { grid-template-columns: 1fr; }
  .contact-form-col { order: -1; }
  .contact-info-panel { position: static; }
  .contact-map-layout { grid-template-columns: 1fr; }
  .contact-map-frame iframe { height: 320px; }
  .contact-map-aside { padding: 28px 24px; }
}
@media (max-width: 640px) {
  .contact-hero-pill { display: none; }
  .contact-trust-row { grid-template-columns: 1fr 1fr; }
  .contact-trust-item {
    border-right: 0;
    border-bottom: 1px solid var(--line);
    padding: 18px 16px;
  }
  .contact-trust-item:nth-child(odd) { border-right: 1px solid var(--line); }
  .contact-trust-item:nth-last-child(-n+2) { border-bottom: 0; }
  .contact-trust-icon {
    width: 44px;
    height: 44px;
    min-width: 44px;
    min-height: 44px;
  }
  .contact-trust-icon svg {
    width: 20px !important;
    height: 20px !important;
  }
  .contact-form-panel { padding: 24px 18px; }
  .contact-faq-head { flex-direction: column; align-items: flex-start; }
  .contact-hero-actions { flex-direction: column; }
  .contact-hero-actions .btn,
  .contact-hero-actions .contact-modal-trigger { width: 100%; justify-content: center; }
}

/* ── Sticky ask bar ── */
.sticky-ask {
  position: fixed;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(18px, env(safe-area-inset-bottom));
  left: auto;
  z-index: 50;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
  padding: 0;
  background: transparent;
  box-shadow: none;
  border-radius: 0;
  /* Avoid translateX past the viewport — that causes phone side-scroll */
  transform: none;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.28s ease, visibility 0.28s ease;
  max-width: none;
}
.sticky-ask.is-on {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}
.sticky-ask-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0;
  height: 56px;
  min-width: 56px;
  padding: 0;
  border-radius: 999px;
  text-decoration: none;
  color: #fff;
  box-shadow: 0 10px 28px rgba(6, 28, 16, 0.32);
  overflow: hidden;
  transition:
    min-width 0.28s var(--ease-spring),
    padding 0.28s var(--ease-spring),
    gap 0.22s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}
.sticky-ask-ico {
  width: 56px;
  height: 56px;
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
}
.sticky-ask-ico svg {
  display: block;
  width: 22px;
  height: 22px;
}
.sticky-ask-label {
  max-width: 0;
  opacity: 0;
  overflow: hidden;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.01em;
  padding-left: 0;
  transition:
    max-width 0.28s var(--ease-spring),
    opacity 0.2s ease,
    padding 0.28s var(--ease-spring);
}
.sticky-ask-call { background: var(--green); color: #fff; }
.sticky-ask-wa { background: #25d366; color: #fff; }
.sticky-ask-quote { background: #fff; color: var(--green-deep); }
.sticky-ask-quote .sticky-ask-ico { color: var(--green); }

@media (hover: hover) and (pointer: fine) {
  .sticky-ask-btn:hover {
    min-width: auto;
    padding-left: 4px;
    gap: 2px;
    transform: translateY(-2px);
    box-shadow: 0 14px 32px rgba(6, 28, 16, 0.38);
  }
  .sticky-ask-btn:hover .sticky-ask-label {
    max-width: 160px;
    opacity: 1;
    padding-left: 18px;
  }
  .sticky-ask-btn:focus-visible {
    outline: 2px solid #9be0a8;
    outline-offset: 3px;
  }
  .sticky-ask-btn:focus-visible {
    min-width: auto;
    padding-left: 4px;
  }
  .sticky-ask-btn:focus-visible .sticky-ask-label {
    max-width: 160px;
    opacity: 1;
    padding-left: 18px;
  }
}

