.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.lead-pop-backdrop {
  position: fixed;
  inset: 0;
  z-index: 80;
  width: 100%;
  height: 100%;
  max-width: 100%;
  background: rgba(6, 28, 14, 0.62);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: safe center;
  justify-content: safe center;
  padding:
    max(12px, env(safe-area-inset-top, 0px))
    max(16px, env(safe-area-inset-right, 0px))
    max(12px, env(safe-area-inset-bottom, 0px))
    max(16px, env(safe-area-inset-left, 0px));
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  scrollbar-width: none;
  -ms-overflow-style: none;
  animation: fadeIn 0.28s ease both;
}
.lead-pop-backdrop::-webkit-scrollbar { display: none; width: 0; height: 0; }
.lead-pop {
  width: min(380px, 100%);
  max-width: 100%;
  max-height: calc(100dvh - 24px);
  margin: auto;
  flex: none;
  background: #fff;
  border-radius: 20px;
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -ms-overflow-style: none;
  box-shadow: 0 28px 80px rgba(8, 30, 16, 0.35);
  position: relative;
  animation: fadeIn 0.32s ease both;
}
.lead-pop::-webkit-scrollbar { display: none; width: 0; height: 0; }
.lead-pop-close {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 2;
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: 50%;
  background: rgba(255,255,255,0.16);
  color: #fff;
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
}
.lead-pop-close:hover { background: rgba(255,255,255,0.28); }
.lead-pop-head {
  background: linear-gradient(145deg, #062312 0%, #0f3d20 55%, #1e8736 160%);
  color: #fff;
  padding: 18px 20px 14px;
}
.lead-pop-mark {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: #fff;
  margin: 0 0 12px;
  overflow: hidden;
  flex: none;
}
.lead-pop-mark img {
  width: 28px;
  height: 28px;
  object-fit: contain;
  display: block;
}
.lead-pop-kicker {
  margin: 0 0 4px;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.55);
  font-weight: 700;
}
.lead-pop-head h2 {
  margin: 0 0 6px;
  font-size: 20px;
  color: #fff;
  letter-spacing: -0.02em;
  line-height: 1.25;
}
.lead-pop-head p {
  margin: 0;
  font-size: 12.5px;
  line-height: 1.4;
  color: rgba(255,255,255,0.78);
}
.lead-pop-form,
.lead-pop-done {
  padding: 14px 18px 16px;
  display: grid;
  gap: 8px;
}
.lead-pop-form label {
  display: grid;
  gap: 4px;
  font-size: 12px;
  font-weight: 650;
  color: var(--ink);
}
.lead-pop-form input,
.lead-pop-form select {
  border: 1.5px solid #dbe5db;
