#quote-form,
[id^="cat-"],
#india-coverage {
  scroll-margin-top: 96px;
}
.service-detail-page .zoom-img {
  border-radius: 16px;
  aspect-ratio: 4 / 3;
  overflow: hidden;
}
.lead-pop-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}
.lead-pop-pills span {
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #062312;
  background: #9be0a8;
  border-radius: 999px;
  padding: 4px 8px;
}
.lead-pop-call {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 650;
  color: var(--green-deep);
  padding: 2px;
}
.lead-pop-call:hover { color: var(--green); }
.drawer-acc { display: flex; flex-direction: column; }
.drawer-acc-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}
.drawer-acc-row a { flex: 1; }
.drawer-acc-tog {
  background: none;
  border: 0;
  padding: 6px;
  cursor: pointer;
  color: var(--muted);
  display: grid;
  place-items: center;
  border-radius: 8px;
  flex: none;
  width: 32px;
  height: 32px;
}
.drawer-acc-tog svg { width: 14px; height: 14px; }
.drawer-acc-tog:hover { background: #e8f3e8; color: var(--green); }
.drawer-acc-panel {
  display: flex;
  flex-direction: column;
  padding: 2px 0 6px 8px;
  border-left: 2px solid #d5e8d8;
  margin: 0 0 2px 10px;
  gap: 0;
}
.drawer-acc-panel a {
  font-size: 13px !important;
  font-weight: 550 !important;
  color: #4d6156 !important;
  padding: 6px 8px !important;
  border-radius: 8px;
}
.drawer-acc-panel a:hover {
  background: #f0f7f1 !important;
  color: var(--green) !important;
}
.owner-portrait img,
.team-lead-media img,
.lead-visual img,
.blog-side-img img,
.contact-form-panel img {
  transition: transform 0.7s ease;
}
.owner-portrait:hover img,
.team-lead:hover .team-lead-media img,
.lead-visual:hover img,
.blog-side-card:hover .blog-side-img img {
  transform: scale(1.06);
}
.page-hero h1,
.page-hero .eyebrow {
  animation: fadeUp 0.7s var(--ease-spring) both;
}
.page-hero p { animation: fadeUp 0.7s var(--ease-spring) both 0.12s; }
.page-hero .hero-cta-row { animation: fadeUp 0.7s var(--ease-spring) both 0.22s; }
.trust-bar { margin-top: 0; position: relative; z-index: 5; }

@media (max-width: 820px) {
  .trust-bar { margin-top: 0; }
}

@media (max-width: 820px) {
  .quote-page-grid { grid-template-columns: 1fr; gap: 22px; }
  .hero-cta-row .btn { width: 100%; justify-content: center; }
  .t-card { min-height: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .page-hero::before,
  .page-hero h1,
  .page-hero p,
  .page-hero .eyebrow,
  .page-hero .hero-cta-row,
  .hero h1, .hero p {
    animation: none !important;
  }
}

/* ══════════════════════════════════════════
   SERVICES V3 — story stack (scroll depth)
══════════════════════════════════════════ */
.services-v3 {
  position: relative;
  padding: 88px 0 96px;
  background:
    radial-gradient(ellipse at 10% 8%, rgba(155, 224, 168, 0.2) 0%, transparent 42%),
    radial-gradient(ellipse at 90% 70%, rgba(30, 135, 54, 0.08) 0%, transparent 40%),
    linear-gradient(180deg, #f4f9f1 0%, #fafcf8 45%, #f2f7ef 100%);
}
.services.services-v3 { padding: 88px 0 96px; }
.svc-story-head {
  max-width: 640px;
  margin: 0 auto 52px;
  text-align: center;
}
.svc-story-head h2 {
  margin: 8px 0 14px;
  font-size: clamp(30px, 4vw, 42px);
  line-height: 1.12;
}
.svc-story-head .lede {
  margin: 0 auto;
  color: var(--muted);
  font-size: 16px;
  line-height: 1.65;
  max-width: 540px;
}
.svc-story-stack {
  display: flex;
  flex-direction: column;
  gap: 28px;
}
.svc-story-stack > .reveal { display: block; }
.svc-story {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 0;
  min-height: 340px;
  border-radius: 28px;
  overflow: hidden;
  background: #fff;
  border: 1px solid #d8e8d4;
  text-decoration: none;
  color: inherit;
  box-shadow: 0 16px 42px rgba(12, 40, 22, 0.08);
  transition: transform 0.35s var(--ease-spring), box-shadow 0.35s ease, border-color 0.3s ease;
}
.svc-story:hover {
  transform: translateY(-6px);
  box-shadow: 0 28px 56px rgba(12, 40, 22, 0.14);
  border-color: #b7d4b0;
}
.svc-story.is-flip {
  grid-template-columns: 0.95fr 1.05fr;
}
.svc-story.is-flip .svc-story-media { order: 2; }
.svc-story.is-flip .svc-story-body { order: 1; }
.svc-story-media {
  position: relative;
  min-height: 340px;
  overflow: hidden;
  background: #0d2a18;
}
.svc-story-media > img,
.svc-story-media .zoom-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border-radius: 0;
}
.svc-story-media > img {
  object-fit: cover;
  display: block;
  transform: scale(1.04);
  transition: transform 0.7s var(--ease-spring);
}
.svc-story-media .zoom-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.svc-story:hover .svc-story-media > img,
.svc-story:hover .svc-story-media .zoom-img img {
  transform: scale(1.08);
  transition: transform 0.8s ease;
}
.svc-story-num {
  position: absolute;
  left: 18px;
  bottom: 18px;
  z-index: 2;
  font-family: var(--font-display);
  font-size: clamp(48px, 6vw, 72px);
  line-height: 0.85;
  letter-spacing: -0.04em;
  color: rgba(255, 255, 255, 0.92);
  text-shadow: 0 8px 28px rgba(0, 0, 0, 0.35);
  pointer-events: none;
}
.svc-story-body {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 36px 40px;
  background: linear-gradient(160deg, #ffffff 0%, #f6faf4 100%);
}
.svc-story-icon {
  width: 48px;
  height: 48px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  margin-bottom: 18px;
  background: linear-gradient(145deg, #e8f6e4 0%, #d4ecd4 100%);
  color: var(--green);
  transition: background 0.3s ease, color 0.3s ease, transform 0.3s ease;
}
.svc-story:hover .svc-story-icon {
  background: var(--green);
  color: #fff;
  transform: scale(1.06);
}
.svc-story-body h3 {
  margin: 0 0 12px;
  font-family: var(--font-display);
  font-size: clamp(24px, 2.6vw, 32px);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--ink);
}
.svc-story-body p {
  margin: 0 0 22px;
  font-size: 15.5px;
  line-height: 1.65;
  color: var(--muted);
  max-width: 38em;
}
.svc-story-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  align-self: flex-start;
  padding: 11px 18px;
  border-radius: 999px;
  background: var(--green-deep);
  color: #fff;
  font-size: 13.5px;
  font-weight: 700;
  transition: transform 0.25s ease, background 0.25s ease;
}
.svc-story:hover .svc-story-cta {
  transform: translateX(4px);
  background: var(--green);
}
.svc-story-foot {
  margin-top: 48px;
  padding: 28px 32px;
  border-radius: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
  background: linear-gradient(120deg, #0c2f1a 0%, #145528 55%, #1e8736 130%);
  color: #fff;
  box-shadow: 0 18px 40px rgba(8, 30, 16, 0.18);
}
.svc-story-foot p {
  margin: 0;
  font-size: 17px;
  font-family: var(--font-display);
  line-height: 1.3;
  max-width: 420px;
}
.svc-story-foot .btn {
  background: #fff;
  color: var(--green-deep);
  border: 0;
}
.svc-story-foot .btn:hover {
  background: #f3fff5;
}

@media (max-width: 900px) {
  .svc-story,
  .svc-story.is-flip {
    grid-template-columns: 1fr;
    min-height: 0;
  }
  .svc-story.is-flip .svc-story-media,
  .svc-story.is-flip .svc-story-body { order: unset; }
  .svc-story-media { min-height: 220px; }
  .svc-story-body { padding: 24px 22px 26px; }
  .svc-story-num { font-size: 52px; left: 14px; bottom: 12px; }
}

@media (max-width: 640px) {
  .services.services-v3 { padding: 52px 0 60px; }
  .svc-story-head { margin-bottom: 28px; text-align: left; }
  .svc-story-head h2 { font-size: 28px; }
  .svc-story-head .lede { font-size: 14.5px; }
  .svc-story-stack { gap: 16px; }
  .svc-story { border-radius: 20px; }
  .svc-story-media { min-height: 190px; }
  .svc-story-body { padding: 20px 18px 22px; }
  .svc-story-body h3 { font-size: 22px; }
  .svc-story-body p { font-size: 14px; margin-bottom: 16px; }
  .svc-story-icon { width: 42px; height: 42px; margin-bottom: 12px; }
  .svc-story-num { font-size: 44px; }
  .svc-story-foot {
    margin-top: 28px;
    padding: 22px 18px;
    flex-direction: column;
    align-items: flex-start;
  }
  .svc-story-foot p { font-size: 18px; }
  .svc-story-foot .btn { width: 100%; justify-content: center; }
}

/* ══════════════════════════════════════════
   SERVICES V2 — bento layout (legacy)
══════════════════════════════════════════ */
.services-v2 {
  position: relative;
  padding: 80px 0 88px;
  background:
    radial-gradient(ellipse at 8% 0%, rgba(155, 224, 168, 0.18) 0%, transparent 45%),
    radial-gradient(ellipse at 92% 100%, rgba(30, 135, 54, 0.08) 0%, transparent 42%),
    linear-gradient(180deg, #f7fbf5 0%, var(--bg) 55%, #f4f9f1 100%);
}
.services.services-v2 { padding: 80px 0 88px; }
.services-v2 .section-header { margin-bottom: 36px; align-items: flex-end; }
.services-v2 .section-header .lede {
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.6;
  max-width: 480px;
}
.svc-bento {
  display: grid;
  grid-template-columns: 1.12fr 0.98fr;
  gap: 16px;
  align-items: stretch;
  min-height: 560px;
}
.svc-bento-feature-wrap { height: 100%; display: flex; }
.svc-bento-grid > .svc-bento-tile { height: 100%; min-height: 0; }
.svc-bento-feature {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 560px;
  width: 100%;
  border-radius: 28px;
  overflow: hidden;
  text-decoration: none;
  color: #fff;
  box-shadow: 0 22px 50px rgba(8, 30, 16, 0.16);
  transition: transform 0.28s var(--ease-spring), box-shadow 0.28s ease;
}
.svc-bento-feature:hover {
  transform: translateY(-4px);
  box-shadow: 0 28px 60px rgba(8, 30, 16, 0.22);
}
.svc-bento-feature-img {
  position: absolute !important;
  inset: 0;
  width: 100%;
  height: 100%;
  border-radius: inherit;
}
.svc-bento-feature-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transform: scale(1);
  opacity: 1;
  transition: transform 0.7s ease;
}
.svc-bento-feature:hover .svc-bento-feature-img img { transform: scale(1.06); }
.svc-bento-feature-shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(0deg, rgba(4, 18, 10, 0.92) 0%, rgba(4, 18, 10, 0.38) 48%, rgba(4, 18, 10, 0.1) 72%),
    radial-gradient(circle at 85% 15%, rgba(30, 135, 54, 0.32) 0%, transparent 45%);
  pointer-events: none;
}
.svc-bento-feature-body {
  position: relative;
  z-index: 1;
  padding: 28px 26px 26px;
}
.svc-bento-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px 6px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(8px);
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 14px;
}
.svc-bento-feature-body h3 {
  margin: 0 0 10px;
  font-family: var(--font-display);
  font-size: clamp(26px, 3vw, 34px);
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.svc-bento-feature-body p {
  margin: 0 0 18px;
  max-width: 420px;
  font-size: 15px;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.82);
}
.svc-bento-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 11px 18px;
  border-radius: 999px;
  background: #fff;
  color: var(--green-deep);
  font-size: 13.5px;
  font-weight: 700;
  transition: transform 0.2s ease, background 0.2s ease;
}
.svc-bento-feature:hover .svc-bento-cta { transform: translateX(4px); background: #f3fff5; }

.svc-bento-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-auto-rows: 1fr;
  gap: 12px;
}
.svc-bento-grid > .svc-bento-tile:last-child {
  grid-column: 1 / -1;
  flex-direction: row;
  align-items: center;
  gap: 16px;
  min-height: 112px;
  padding: 18px 20px;
}
.svc-bento-grid > .svc-bento-tile:last-child .svc-bento-tile-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.svc-bento-grid > .svc-bento-tile:last-child .svc-bento-tile-go {
  margin-left: auto;
  opacity: 1;
  transform: none;
  align-self: center;
}

.svc-bento-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  height: 100%;
  min-height: 148px;
  padding: 18px 16px 16px;
  border-radius: 20px;
  background: #fff;
  border: 1px solid #dceadc;
  text-decoration: none;
  overflow: hidden;
  box-shadow: 0 8px 24px rgba(16, 48, 28, 0.06);
  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.35s ease,
    border-color 0.3s ease,
    background 0.3s ease;
}
.svc-bento-tile::before {
  content: "";
  position: absolute;
  inset: 0 auto auto 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(90deg, var(--green) 0%, #9be0a8 100%);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.25s ease;
}
.svc-bento-tile:hover {
  transform: translateY(-4px);
  border-color: #b7d4b0;
  box-shadow: 0 16px 36px rgba(16, 48, 28, 0.12);
}
.svc-bento-tile:hover::before { transform: scaleX(1); }
.svc-bento-tile-num {
  position: absolute;
  top: 10px;
  right: 12px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: rgba(30, 135, 54, 0.35);
}
.svc-bento-tile-icon {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: linear-gradient(145deg, #eef8ea 0%, #dcefdc 100%);
  color: var(--green);
  flex: none;
  transition:
    background 0.35s ease,
    color 0.35s ease,
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}
.svc-bento-tile:hover .svc-bento-tile-icon {
  background: var(--green);
  color: #fff;
  transform: scale(1.05);
}
.svc-bento-tile-copy { flex: 1; min-width: 0; }
.svc-bento-tile-copy strong {
  display: block;
  font-size: 15px;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.25;
  margin-bottom: 4px;
  padding-right: 28px;
}
.svc-bento-tile-copy span {
  display: block;
  font-size: 13px;
  color: var(--muted);
  line-height: 1.45;
}
.svc-bento-tile-go {
  align-self: flex-start;
  color: var(--green);
  opacity: 0;
  transform: translateX(-4px);
  transition: opacity 0.2s ease, transform 0.2s ease;
}
.svc-bento-tile:hover .svc-bento-tile-go {
  opacity: 1;
  transform: none;
}

/* ══════════════════════════════════════════
   WHY US V2 — bento layout
══════════════════════════════════════════ */
.why-us-v2 {
  position: relative;
  overflow: hidden;
  padding: 72px 0 80px;
}
.why-us-v2-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 12% 0%, rgba(155, 224, 168, 0.22) 0%, transparent 52%),
    radial-gradient(ellipse at 88% 100%, rgba(30, 135, 54, 0.10) 0%, transparent 48%),
    linear-gradient(180deg, #f7fbf5 0%, #edf5e9 100%);
  pointer-events: none;
}
.why-us-v2 .wrap { position: relative; z-index: 1; }
.why-us-head {
  text-align: center;
  max-width: 580px;
  margin: 0 auto 44px;
}
.why-us-head h2 { margin: 8px 0 12px; }
.why-bento {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 14px;
}
.why-bento > .fade-up.fill,
.why-bento > .why-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-width: 0;
}
.why-bento > .fade-up.fill > .why-card { width: 100%; flex: 1; }
.why-bento > .fade-up.fill:nth-child(1),
.why-bento > .why-card:nth-child(1) { grid-column: span 6; }
.why-bento > .fade-up.fill:nth-child(2),
.why-bento > .why-card:nth-child(2) { grid-column: span 3; }
.why-bento > .fade-up.fill:nth-child(3),
.why-bento > .why-card:nth-child(3) { grid-column: span 3; }
.why-bento > .fade-up.fill:nth-child(4),
.why-bento > .why-card:nth-child(4) { grid-column: span 4; }
.why-bento > .fade-up.fill:nth-child(5),
.why-bento > .why-card:nth-child(5) { grid-column: span 4; }
.why-bento > .fade-up.fill:nth-child(6),
.why-bento > .why-card:nth-child(6) { grid-column: span 4; }
.why-card {
  position: relative;
  height: 100%;
  padding: 24px 22px 22px;
  border-radius: 22px;
  background: #fff;
  border: 1px solid #dceadc;
  box-shadow: 0 10px 28px rgba(16, 48, 28, 0.06);
  overflow: hidden;
  transition: transform 0.24s var(--ease-spring), box-shadow 0.24s ease, border-color 0.24s ease;
}
.why-card::after {
  content: "";
  position: absolute;
  inset: auto -20% -40% auto;
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(30, 135, 54, 0.08) 0%, transparent 70%);
  pointer-events: none;
}
.why-card:hover {
  transform: translateY(-5px);
  border-color: #b7d4b0;
  box-shadow: 0 18px 40px rgba(16, 48, 28, 0.12);
}
.why-card-num {
  position: absolute;
  top: 14px;
  right: 16px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: rgba(30, 135, 54, 0.28);
}
.why-card-icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  margin-bottom: 14px;
  border-radius: 15px;
  background: linear-gradient(145deg, #eef8ea 0%, #dcefdc 100%);
  color: var(--green);
  transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease;
}
.why-card:hover .why-card-icon {
  background: var(--green);
  color: #fff;
  transform: scale(1.06);
}
.why-card h3 {
  margin: 0 0 8px;
  font-family: var(--font-body);
  font-size: 17px;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.25;
}
.why-card p {
  margin: 0;
  font-size: 14px;
  line-height: 1.55;
  color: var(--muted);
}
.why-card-lead {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  text-align: left;
  background: linear-gradient(145deg, #062312 0%, #0f3d20 55%, #1a5c30 100%);
  border-color: rgba(255, 255, 255, 0.08);
  color: #fff;
  min-height: 240px;
}
.why-card-lead::after { background: radial-gradient(circle, rgba(155, 224, 168, 0.15) 0%, transparent 70%); }
.why-card-lead .why-card-num { color: rgba(255, 255, 255, 0.25); }
.why-card-lead .why-card-icon {
  background: #fff;
  color: var(--green-deep);
  border: 0;
  margin: 0 0 14px;
