/* ══════════════════════════════════════════
   PREMIUM SUITE + FOOTER SERVICES
══════════════════════════════════════════ */
.svc-suite {
  margin-top: 36px;
  padding: 28px;
  border-radius: var(--radius);
  background:
    linear-gradient(160deg, rgba(255,255,255,0.92) 0%, rgba(232,244,234,0.75) 100%);
  border: 1px solid var(--line);
  box-shadow: var(--shadow-sm);
}
.svc-suite-head {
  margin-bottom: 18px;
}
.svc-suite-head h3 {
  margin: 8px 0 0;
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--ink);
}
.svc-suite-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.svc-suite-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-radius: var(--radius-sm);
  background: #fff;
  border: 1px solid #dcead9;
  text-decoration: none;
  transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
}
.svc-suite-card:hover {
  border-color: #a8c9b0;
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}
.svc-suite-icon {
  width: 40px;
  height: 40px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: linear-gradient(145deg, #eef8ea, #dcefdc);
  color: var(--green);
}
.svc-suite-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.svc-suite-copy strong {
  font-size: 14.5px;
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.01em;
}
.svc-suite-copy em {
  font-style: normal;
  font-size: 12.5px;
  color: var(--muted);
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.svc-suite-go {
  color: var(--green);
  font-size: 16px;
  font-weight: 700;
}
.footer-link-col-services { min-width: 0; }
.footer-services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 6px;
  margin-bottom: 10px;
}
.footer-services-grid a {
  font-size: 13.5px;
  line-height: 1.35;
}
.footer-services-all {
  display: inline-flex;
  margin-top: 4px;
  font-size: 13px;
  font-weight: 700;
  color: #9be0a8 !important;
}
.page-section {
  padding: 28px 0 72px;
}
.why-card,
.audience-card-v2,
.svc-extra-card {
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
}

@media (max-width: 820px) {
  .svc-suite { padding: 18px 14px; margin-top: 24px; }
  .svc-suite-grid { grid-template-columns: 1fr; }
  .svc-suite-head h3 { font-size: 22px; }
  .nav-menu {
    max-height: min(70vh, 520px);
